fn hydrated_ledger_manager(path: String) -> crate::store::LedgerManager {
    let manager = crate::store::LedgerManager::new(path);
    if let Err(err) = manager.load() {
        tracing::warn!(
            "Connection ledger could not be loaded, starting empty: {:?}",
            err
        );
    }
    manager
}

