    tracing::info!("Nickname set to {:?}", nickname);
    self.audit_log.write().append(
        AuditEventType::ConsentGranted,
        identity.identity_id(),
        None,
        Some(format!("nickname={}", nickname)),
    );
    Ok(())
}

