    let restored = IBLT::from_bytes(&bytes).unwrap();

    assert_eq!(iblt.cell_count(), restored.cell_count());

    // Verify it still decodes the same way
    let empty = IBLT::new(2);
    let diff_orig = iblt.subtract(&empty).unwrap();
