pub fn priority_score(&self) -> f64 {
    let now = web_time::SystemTime::now()
        .duration_since(web_time::UNIX_EPOCH)
        .unwrap_or_default()
        .as_secs() as f64;

    let age_hours = (now - self.created_at as f64) / 3600.0;
    let recency = (-age_hours / 24.0).exp(); // τ = 24 hours

    let hop_penalty = 1.0 / (1.0 + self.hop_count as f64);

    let ttl_factor = if self.ttl_expiry == 0 {
        1.0 // No expiry = full score
    } else {
        let total_lifetime = (self.ttl_expiry as f64) - (self.created_at as f64);
        let remaining = (self.ttl_expiry as f64) - now;
        if total_lifetime <= 0.0 || remaining <= 0.0 {
            0.0 // Expired
        } else {
            (remaining / total_lifetime).clamp(0.0, 1.0)
        }
    };

    (self.priority as f64) * recency * hop_penalty * ttl_factor
}

pub fn new() -> Self {
    Self {
        messages: HashMap::new(),
        max_messages: MAX_MESSAGES,
        backend: None,
    }
}

pub fn with_capacity(max: usize) -> Self {
    Self {
        messages: HashMap::new(),
        max_messages: max,
        backend: None,
    }
}

pub fn persistent(backend: Arc<dyn crate::store::backend::StorageBackend>) -> Self {
    let mut store = Self {
        messages: HashMap::new(),
        max_messages: MAX_MESSAGES,
        backend: Some(backend.clone()),
    };
    if let Err(e) = store.load(backend.as_ref()) {
        tracing::error!("Failed to load persistent drift state: {}", e);
    }
    store
}

pub fn insert(&mut self, envelope: StoredEnvelope) -> bool {
    if self.messages.contains_key(&envelope.message_id) {
        return false; // Duplicate — CRDT idempotent
    }
    if let Some(backend) = &self.backend {
        let key = [b"drift:", envelope.message_id.as_slice()].concat();
        match bincode::serialize(&envelope) {
            Ok(value) => {
                if let Err(e) = backend.put(&key, &value) {
                    tracing::error!("Failed to write-through insert in MeshStore: {}", e);
                }
            }
            Err(e) => {
                tracing::error!("Failed to serialize envelope in MeshStore insert: {}", e);
            }
        }
    }
    self.messages.insert(envelope.message_id, envelope);
    self.evict_if_over_budget();
    true
}

pub fn merge(&mut self, other: &MeshStore) {
    for (id, envelope) in &other.messages {
        if !self.messages.contains_key(id) {
            self.insert(envelope.clone());
        }
    }
}

pub fn get(&self, id: &MessageId) -> Option<&StoredEnvelope> {
    self.messages.get(id)
}

pub fn contains(&self, id: &MessageId) -> bool {
    self.messages.contains_key(id)
}

pub fn message_ids(&self) -> Vec<MessageId> {
    self.messages.keys().copied().collect()
}

pub fn messages_for_recipient(&self, hint: &[u8; 4]) -> Vec<&StoredEnvelope> {
    self.messages
        .values()
        .filter(|e| &e.recipient_hint == hint)
        .collect()
}

pub fn by_priority(&self) -> Vec<&StoredEnvelope> {
    let mut msgs: Vec<_> = self.messages.values().collect();
    msgs.sort_by(|a, b| {
        b.priority_score()
            .partial_cmp(&a.priority_score())
            .unwrap_or(std::cmp::Ordering::Equal)
    });
    msgs
}

pub fn len(&self) -> usize {
    self.messages.len()
}

pub fn is_empty(&self) -> bool {
    self.messages.is_empty()
}

pub fn remove(&mut self, id: &MessageId) -> bool {
    let removed = self.messages.remove(id).is_some();
    if removed {
        if let Some(backend) = &self.backend {
            let key = [b"drift:", id.as_slice()].concat();
            if let Err(e) = backend.remove(&key) {
                tracing::error!("Failed to write-through remove in MeshStore: {}", e);
            }
        }
    }
    removed
}

pub fn remove_expired(&mut self) -> usize {
    let now = web_time::SystemTime::now()
        .duration_since(web_time::UNIX_EPOCH)
        .unwrap_or_default()
        .as_secs() as u32;
    let expired_ids: Vec<MessageId> = self
        .messages
        .iter()
        .filter(|(_, e)| e.ttl_expiry != 0 && e.ttl_expiry <= now)
        .map(|(id, _)| *id)
        .collect();
    let mut removed = 0;
    for id in expired_ids {
        if self.remove(&id) {
            removed += 1;
        }
    }
    removed
}

pub fn generate_proof(&self) -> String {
    let mut hasher = blake3::Hasher::new();

    // Hash message IDs in sorted order for determinism
    let mut ids = self.message_ids();
    ids.sort();

    for id in ids {
        hasher.update(&id);
    }

    hex::encode(hasher.finalize().as_bytes())
}

fn evict_if_over_budget(&mut self) {
    while self.messages.len() > self.max_messages {
        // Find the message with the lowest priority score
        let lowest_id = self
            .messages
            .iter()
            .min_by(|a, b| {
                a.1.priority_score()
                    .partial_cmp(&b.1.priority_score())
                    .unwrap_or(std::cmp::Ordering::Equal)
            })
            .map(|(id, _)| *id);
        if let Some(id) = lowest_id {
            self.remove(&id);
        } else {
            break;
        }
    }
}

pub fn save(&self, backend: &dyn crate::store::backend::StorageBackend) -> Result<(), String> {
    for (id, envelope) in &self.messages {
        let key = [b"drift:", id.as_slice()].concat();
        let value = bincode::serialize(envelope)
            .map_err(|e| format!("Failed to serialize envelope: {}", e))?;
        backend.put(&key, &value)?;
    }
    Ok(())
}

