    let mut store_a = MeshStore::with_capacity(2);
    let mut store_b = MeshStore::with_capacity(2);

    // Both stores start with msg_id [1] and [2]
    store_a.insert(make_envelope([1u8; 16], 100, 0, 1000, 0));
