        created_at: 1234567890,
        ttl_expiry: 1234567990,
        hop_count: 0,
        priority: 0,
        sender_public_key: sender_pk,
        ephemeral_public_key: ephemeral_pk,
        nonce,
        signature,
        ciphertext: ciphertext.clone(),
        ratchet_dh_public: None,
        ratchet_message_number: None,
