pub fn new(peer_id: String, addresses: Vec<String>, inviter_public_key: Vec<u8>) -> Self {
    let now = SystemTime::now()
        .duration_since(UNIX_EPOCH)
        .unwrap_or_default()
        .as_secs();

    Self {
        peer_id,
        addresses,
        group_key_hint: None,
        created_at: now,
        expires_at: now + 24 * 3600, // Valid for 24 hours
        inviter_public_key,
        pq_public_key: None,
        signature: Vec::new(),
        pq_signature: None,
    }
}

pub fn with_group_key(mut self, hint: String) -> Self {
    self.group_key_hint = Some(hint);
    self
}

pub fn with_expiry(mut self, duration_secs: u64) -> Self {
    self.expires_at = self.created_at + duration_secs;
    self
}

pub fn is_unexpired_and_shaped(&self, require_pq: bool) -> bool {
    let now = SystemTime::now()
        .duration_since(UNIX_EPOCH)
        .unwrap_or_default()
        .as_secs();

    if now >= self.expires_at {
        return false;
    }

    match (&self.pq_signature, require_pq) {
        (Some(pq_sig), _) if pq_sig.is_empty() => false,
        (None, true) => false,
        (None, false) => {
            tracing::warn!(
                peer_id = %self.peer_id,
                "accepted a legacy single-signature bootstrap invite shape \
                 (NOT cryptographically verified)"
            );
            true
        }
        _ => true,
    }
}

pub fn to_bytes(&self) -> Result<Vec<u8>, BootstrapError> {
