fn test_wakeup_payload_creation() {
    let payload = WakeUpPayload::new([1, 2, 3, 4], [5, 6, 7, 8], true);
    assert_eq!(payload.recipient_hint, [1, 2, 3, 4]);
    assert_eq!(payload.relay_hint, [5, 6, 7, 8]);
