    assert!(cache.is_definitely_unreachable("peer1"));

    // Wait for expiry
    std::thread::sleep(Duration::from_millis(150));

    // Should no longer be definitely unreachable
    assert!(!cache.is_definitely_unreachable("peer1"));
}

