        TransportType::TCP,
    );

    assert_eq!(table.gateway_count(), 1);

    // Advance time beyond max staleness
    let now = current_timestamp() + 101;
    let evicted = table.cleanup(now);

    assert_eq!(evicted, 1);
    assert_eq!(table.gateway_count(), 0);
}

