fn private_ranges_follow_network_mode() {
    assert!(is_dialable_multiaddr(
        "/ip4/10.0.2.16/tcp/9001",
        LOCAL,
        REMOTE
    ));
    assert!(is_dialable_multiaddr(
        "/ip4/192.168.1.5/tcp/9001",
