pub fn best_relays(&self, count: usize) -> Vec<PeerId> {
    let mut peers: Vec<_> = self.reputations.values().collect();
    peers.sort_by(|a, b| {
        b.score
            .total_cmp(&a.score)
            .then_with(|| a.peer_id.to_string().cmp(&b.peer_id.to_string()))
    });

    peers
        .into_iter()
        .filter(|r| r.is_reliable)
        .take(count)
        .map(|r| r.peer_id)
        .collect()
}

