async fn is_available(&self) -> Result<bool, WifiAwareError> {
    Ok(self.available)
}

async fn unpublish_service(&self) -> Result<(), WifiAwareError> {
    Ok(())
}

async fn unsubscribe_from_services(&self) -> Result<(), WifiAwareError> {
    Ok(())
