    let request3 = GattWriteRequest::new(GattCharacteristic::Write, vec![0x03]).expect("Valid");

    queue.enqueue(request1).expect("Enqueue 1");
    queue.enqueue(request2).expect("Enqueue 2");
    queue.enqueue(request3).expect("Enqueue 3");

    assert_eq!(queue.dequeue().expect("Dequeue").data[0], 0x01);
    assert_eq!(queue.dequeue().expect("Dequeue").data[0], 0x02);
    assert_eq!(queue.dequeue().expect("Dequeue").data[0], 0x03);
}

pub fn value(&self) -> u16 {
    *self as u16
}

fn default() -> Self {
    Self {
        psm: ProtocolServiceMultiplexer::SCMessenger,
        mtu: 672,
        timeout_secs: 30,
    }
}

pub fn new(psm: ProtocolServiceMultiplexer) -> Self {
    Self {
        psm,
        mtu: 672,
        timeout_secs: 30,
    }
}

pub fn with_mtu(mut self, mtu: u16) -> Self {
    self.mtu = mtu;
    self
}

pub fn with_timeout(mut self, secs: u64) -> Self {
    self.timeout_secs = secs;
    self
}

pub fn validate(&self) -> Result<(), L2capError> {
    if self.mtu < 23 {
        return Err(L2capError::InvalidMtu(self.mtu));
    }
    if self.timeout_secs == 0 {
        return Err(L2capError::InvalidTimeout);
    }
    Ok(())
}

pub fn new(total_fragments: u16, fragment_index: u16) -> Result<Self, L2capError> {
    if fragment_index >= total_fragments {
        return Err(L2capError::FragmentationError(
            "Fragment index out of range".to_string(),
        ));
    }
    Ok(Self {
        total_fragments,
        fragment_index,
    })
}

pub fn to_bytes(&self) -> [u8; 4] {
    let mut bytes = [0u8; 4];
    bytes[0..2].copy_from_slice(&self.total_fragments.to_le_bytes());
    bytes[2..4].copy_from_slice(&self.fragment_index.to_le_bytes());
    bytes
}

pub fn from_bytes(bytes: &[u8]) -> Result<Self, L2capError> {
    if bytes.len() < Self::HEADER_SIZE {
        return Err(L2capError::ReassemblyError(
            "Fragment header too short".to_string(),
        ));
    }
    let total_fragments = u16::from_le_bytes([bytes[0], bytes[1]]);
    let fragment_index = u16::from_le_bytes([bytes[2], bytes[3]]);
    Self::new(total_fragments, fragment_index)
}

pub fn new(config: L2capConfig) -> Result<Self, L2capError> {
    config.validate()?;
    Ok(Self {
        state: ChannelState::Closed,
        config,
    })
}

pub fn state(&self) -> ChannelState {
    self.state
}

pub fn config(&self) -> &L2capConfig {
    &self.config
}

pub fn is_connected(&self) -> bool {
    self.state == ChannelState::Connected
}

pub fn initiate_connection(&mut self) -> Result<(), L2capError> {
    match self.state {
        ChannelState::Closed => {
            self.state = ChannelState::Connecting;
            Ok(())
        }
        ChannelState::Connecting | ChannelState::Connected => Err(L2capError::AlreadyConnected),
        ChannelState::Closing => Err(L2capError::ConnectionFailed(
            "Channel is closing".to_string(),
        )),
    }
}

pub fn confirm_connection(&mut self) -> Result<(), L2capError> {
    match self.state {
        ChannelState::Connecting => {
            self.state = ChannelState::Connected;
            Ok(())
        }
        _ => Err(L2capError::ConnectionFailed(
            "Not in connecting state".to_string(),
        )),
    }
}

pub fn initiate_close(&mut self) -> Result<(), L2capError> {
    match self.state {
        ChannelState::Connected | ChannelState::Connecting => {
            self.state = ChannelState::Closing;
            Ok(())
        }
        ChannelState::Closed => Err(L2capError::NotConnected),
        ChannelState::Closing => Ok(()), // Already closing
    }
}

pub fn confirm_close(&mut self) -> Result<(), L2capError> {
    match self.state {
        ChannelState::Closing | ChannelState::Connected | ChannelState::Connecting => {
            self.state = ChannelState::Closed;
            Ok(())
        }
        ChannelState::Closed => Ok(()), // Already closed
    }
}

pub fn new(config: L2capConfig) -> Result<Self, L2capError> {
    config.validate()?;
    Ok(Self { config })
}

fn max_payload_per_fragment(&self) -> usize {
    // MTU - fragment header
    self.config.mtu as usize - FragmentHeader::HEADER_SIZE
}

pub fn fragment(&self, data: &[u8]) -> Result<Vec<Vec<u8>>, L2capError> {
    let max_payload = self.max_payload_per_fragment();

    if data.is_empty() {
        return Ok(vec![Vec::new()]);
    }

    let total_fragments = data.len().div_ceil(max_payload);

    if total_fragments > u16::MAX as usize {
        return Err(L2capError::FragmentationError(
            "Message too large for fragmentation".to_string(),
        ));
    }

    let mut fragments = Vec::new();

    for (index, chunk) in data.chunks(max_payload).enumerate() {
        let header = FragmentHeader::new(total_fragments as u16, index as u16)?;
        let mut fragment = header.to_bytes().to_vec();
        fragment.extend_from_slice(chunk);
        fragments.push(fragment);
    }

    Ok(fragments)
}

pub fn new(config: L2capConfig) -> Result<Self, L2capError> {
    config.validate()?;
    Ok(Self { config })
}

pub fn reassemble(&self, fragments: &[Vec<u8>]) -> Result<Vec<u8>, L2capError> {
    if fragments.is_empty() {
        return Ok(Vec::new());
    }

    // Parse first fragment to get total count
    let first_header = FragmentHeader::from_bytes(&fragments[0])?;
    let expected_total = first_header.total_fragments as usize;

    if fragments.len() != expected_total {
        return Err(L2capError::ReassemblyError(format!(
            "Expected {} fragments, got {}",
            expected_total,
            fragments.len()
        )));
    }

    // Verify all fragments are present and in order
    for (i, fragment) in fragments.iter().enumerate() {
        let header = FragmentHeader::from_bytes(fragment)?;
        if header.fragment_index as usize != i {
            return Err(L2capError::ReassemblyError(format!(
                "Fragment out of order: expected index {}, got {}",
                i, header.fragment_index
            )));
        }
        if header.total_fragments != first_header.total_fragments {
            return Err(L2capError::ReassemblyError(
                "Inconsistent fragment count".to_string(),
            ));
        }
    }

    // Reassemble payload
    let mut result = Vec::new();
    for fragment in fragments {
        if fragment.len() > FragmentHeader::HEADER_SIZE {
            result.extend_from_slice(&fragment[FragmentHeader::HEADER_SIZE..]);
        }
    }

    Ok(result)
}

pub fn new(reassembly_timeout_secs: u64, max_peer_memory_bytes: usize) -> Self {
    Self {
        reassembly_timeout: std::time::Duration::from_secs(reassembly_timeout_secs),
        max_peer_memory_bytes,
        partials: HashMap::new(),
        drop_stats: HashMap::new(),
    }
}

pub fn with_defaults() -> Self {
    Self::new(30, 256 * 1024) // 30s timeout, 256 KiB cap
}

pub fn feed_fragment(&mut self, peer_id: &str, fragment: &[u8]) -> Option<Vec<u8>> {
    self.evict_expired();

    let header = match FragmentHeader::from_bytes(fragment) {
        Ok(h) => h,
        Err(_) => return None,
    };

    let payload = if fragment.len() > FragmentHeader::HEADER_SIZE {
        &fragment[FragmentHeader::HEADER_SIZE..]
    } else {
        &[]
    };

    let partial =
        self.partials
            .entry(peer_id.to_string())
            .or_insert_with(|| PartialReassembly {
                fragments: HashMap::new(),
                expected_total: header.total_fragments,
                received_at: Instant::now(),
                bytes_stored: 0,
            });

    // Check memory cap before inserting
    if partial.bytes_stored + payload.len() > self.max_peer_memory_bytes {
        self.drop_stats
            .entry(DropReason::MemoryCapExceeded)
            .and_modify(|c| *c += 1)
            .or_insert(1);
        self.partials.remove(peer_id);
        return None;
    }

    partial
        .fragments
        .insert(header.fragment_index, payload.to_vec());
    partial.bytes_stored += payload.len();

    // Check if we have all fragments
    if partial.fragments.len() == partial.expected_total as usize {
        // Invariant: `peer_id`'s entry was created/touched above via `entry().or_insert_with()`
        // in this same synchronous, non-reentrant call, and the only eviction pass
        // (`evict_expired()`) already ran earlier at the top of this function -- so this
        // remove cannot miss today. The `?` is a safety net, not an expected path: if this
        // ever returns None, a future refactor broke that invariant (e.g. an `.await` or
        // re-entrant call introduced between the entry creation above and here).
        let partial = self.partials.remove(peer_id)?;
        let mut reassembled = Vec::new();
        for i in 0..partial.expected_total {
            if let Some(chunk) = partial.fragments.get(&i) {
                reassembled.extend_from_slice(chunk);
            }
        }

        // CRC32 verification: last 4 bytes of reassembled data are the CRC
        if reassembled.len() >= 4 {
            let data_len = reassembled.len() - 4;
            let expected_crc = u32::from_le_bytes([
                reassembled[data_len],
                reassembled[data_len + 1],
                reassembled[data_len + 2],
                reassembled[data_len + 3],
            ]);
            let actual_crc = crc32(&reassembled[..data_len]);
            if expected_crc != actual_crc {
                self.drop_stats
                    .entry(DropReason::CrcMismatch)
                    .and_modify(|c| *c += 1)
                    .or_insert(1);
                return None;
            }
            reassembled.truncate(data_len);
        }

        Some(reassembled)
    } else {
        None
    }
}

fn evict_expired(&mut self) {
    let now = Instant::now();
    let timeout = self.reassembly_timeout;
    let expired: Vec<String> = self
        .partials
        .iter()
        .filter(|(_, p)| now.duration_since(p.received_at) > timeout)
        .map(|(k, _)| k.clone())
        .collect();

    for peer_id in expired {
        self.partials.remove(&peer_id);
        self.drop_stats
            .entry(DropReason::Timeout)
            .and_modify(|c| *c += 1)
            .or_insert(1);
    }
}

pub fn drop_stats(&self) -> &HashMap<DropReason, u64> {
    &self.drop_stats
}

pub fn active_count(&self) -> usize {
    self.partials.len()
}

fn crc32(data: &[u8]) -> u32 {
    let mut crc: u32 = 0xFFFFFFFF;
    for &byte in data {
        crc ^= byte as u32;
        for _ in 0..8 {
            if crc & 1 != 0 {
                crc = (crc >> 1) ^ 0xEDB88320;
            } else {
                crc >>= 1;
            }
        }
    }
    crc ^ 0xFFFFFFFF
}

pub fn append_crc32(data: &mut Vec<u8>) {
    let crc = crc32(data);
    data.extend_from_slice(&crc.to_le_bytes());
}

