pub fn parse_intent(req: &JsonRpcRequest) -> Result<ClientIntent, JsonRpcErrorBody> {
    if req.jsonrpc != "2.0" {
        return Err(JsonRpcErrorBody {
            code: ERR_PARSE,
            message: "jsonrpc must be \"2.0\"".to_string(),
            data: None,
        });
    }

    match req.method.as_str() {
        "send_message" => {
            let recipient = req
                .params
                .get("recipient")
                .and_then(|v| v.as_str())
                .ok_or_else(|| JsonRpcErrorBody {
                    code: ERR_PARAMS,
                    message: "missing recipient".to_string(),
                    data: None,
                })?
                .to_string();
            let message = req
                .params
                .get("message")
                .and_then(|v| v.as_str())
                .ok_or_else(|| JsonRpcErrorBody {
                    code: ERR_PARAMS,
                    message: "missing message".to_string(),
                    data: None,
                })?
                .to_string();
            let id = req
                .params
                .get("id")
                .and_then(|v| v.as_str())
                .map(String::from);
            Ok(ClientIntent::SendMessage {
                recipient,
                message,
                id,
            })
        }
        "scan_peers" => Ok(ClientIntent::ScanPeers {}),
        "get_topology" => Ok(ClientIntent::GetTopology {}),
        "get_identity" => Ok(ClientIntent::GetIdentity {}),
        "initialize_identity" => Ok(ClientIntent::InitializeIdentity {}),
        // ── Contacts ──
        "get_contacts" => Ok(ClientIntent::GetContacts {}),
        "add_contact" => {
            let peer_id = req
                .params
                .get("peer_id")
                .and_then(|v| v.as_str())
                .ok_or_else(|| JsonRpcErrorBody {
                    code: ERR_PARAMS,
                    message: "missing peer_id".to_string(),
                    data: None,
                })?
                .to_string();
            let nickname = req
                .params
                .get("nickname")
                .and_then(|v| v.as_str())
                .map(String::from);
            Ok(ClientIntent::AddContact { peer_id, nickname })
        }
        "remove_contact" => {
            let peer_id = req
                .params
                .get("peer_id")
                .and_then(|v| v.as_str())
                .ok_or_else(|| JsonRpcErrorBody {
                    code: ERR_PARAMS,
                    message: "missing peer_id".to_string(),
