fun hasConversationWith(peerId: String): Boolean {
    val canonical = canonicalId(peerId)
    return try {
        // Check if we have any message history with this peer
        historyManager?.conversation(canonical, 1u)?.isNotEmpty() == true
    } catch (e: Exception) {
