override suspend fun doWork(): Result {
    Timber.i("MeshSyncWorker: background maintenance cycle triggered")
    return try {
        val entryPoint = EntryPointAccessors.fromApplication(
            applicationContext,
            MeshSyncWorkerEntryPoint::class.java
        )
        val meshRepository = entryPoint.getMeshRepository()
        val meshService = meshRepository.getMeshService()
        if (meshService != null && meshService.isRunning()) {
            val core = meshService.getCore()
            if (core != null) {
                // Run maintenance cycle with a 25-second budget
                val report = core.runMaintenanceCycle(25000u)
                Timber.i("MeshSyncWorker: maintenance cycle report: $report")
            } else {
                Timber.w("MeshSyncWorker: IronCore instance not available")
            }
        } else {
            Timber.w("MeshSyncWorker: MeshService is not running or initialized")
        }
        Result.success()
    } catch (e: Exception) {
        Timber.e(e, "MeshSyncWorker: maintenance cycle failed")
        Result.failure()
    }
}

private fun startVpn() {
    if (isRunning) {
        Timber.w("VPN already running")
        return
    }

    try {
        // Create a dummy VPN interface for persistence (no traffic routing)
        // Do NOT add routes - we only want the VPN to keep the service alive,
        // not to intercept network traffic which would break all connectivity
        val builder = Builder()
            .setSession("SCMessenger VPN")
            .addAddress("10.255.255.1", 32)

        if (Build.VERSION.SDK_INT >= Build.VERSION_CODES.Q) {
            builder.setBlocking(false)
        }

        vpnInterface = builder.establish()
        if (vpnInterface == null) {
            Timber.e("Failed to establish VPN interface")
            isRunning = false
            return
        }
        isRunning = true

        Timber.i("VPN service started (dummy tunnel for persistence, no routing)")

        // Start a thread to keep the interface alive
        // In a real VPN, this would forward packets
        Thread {
            try {
                val iface = vpnInterface
                if (iface == null) {
                    Timber.e("VPN interface is null, cannot start packet loop")
                    return@Thread
                }

                val input = FileInputStream(iface.fileDescriptor)
                val packet = ByteBuffer.allocate(32767)

                while (isRunning) {
                    // Read any incoming packets (there won't be any)
                    val length = input.channel.read(packet)
                    if (length > 0) {
                        // Ignore - we don't process anything
                        packet.clear()
                    }
                    Thread.sleep(100)
                }
            } catch (e: Exception) {
                Timber.e(e, "VPN thread error")
            }
        }.start()

    } catch (e: Exception) {
        Timber.e(e, "Failed to start VPN")
        stopSelf()
    }
}

private fun stopVpn() {
    if (!isRunning) {
        return
    }

    try {
        isRunning = false
        vpnInterface?.close()
        vpnInterface = null

        Timber.i("VPN service stopped")
    } catch (e: Exception) {
        Timber.e(e, "Failed to stop VPN")
    } finally {
        stopSelf()
    }
}

fun recordAnrEvent(durationMs: Long, context: String = "") {
    val timestamp = System.currentTimeMillis()
    val eventId = "anr_${timestamp}"

    val anrEvent = AnrEvent(
        eventId = eventId,
        timestamp = timestamp,
        durationMs = durationMs,
        context = context,
        androidVersion = Build.VERSION.SDK_INT,
        device = "${Build.BRAND}_${Build.MODEL}"
    )

    anrEvents[eventId] = anrEvent
    totalAnrEvents++

    Timber.e("ANR Event: duration=%dms, context=%s, total=%d", durationMs, context, totalAnrEvents)

    // Write event to file
    writeAnrEvent(anrEvent)

    // Keep only last 100 events
    if (anrEvents.size > 100) {
        anrEvents.keys.take(anrEvents.size - 100).forEach { anrEvents.remove(it) }
    }
}

fun getServiceUptimeMs(): Long {
