fun onServiceFound(serviceInfo: NsdServiceInfo) {
    Timber.d("mDNS service found: ${serviceInfo.serviceName} type: ${serviceInfo.serviceType}")

    // Only process services of our type
    val typeStripped = serviceInfo.serviceType.trimEnd('.')
    val targetStripped = serviceType.trimEnd('.')
    if (typeStripped.equals(targetStripped, ignoreCase = true)) {
        resolveService(serviceInfo)
    }
}

fun onServiceLost(serviceInfo: NsdServiceInfo) {
    val serviceName = serviceInfo.serviceName
    Timber.d("mDNS service lost: $serviceName")

    // Remove peer from discovered list. If the peer was never resolved
    // (e.g. lost between onServiceFound and onServiceResolved), the
    // entry is absent — that's fine, we still forward a disconnect
    // hint below using the same id derivation.
    val removed = discoveredPeers.remove(serviceName)
    if (removed != null) {
        Timber.i("mDNS peer removed from discovered list: $serviceName")
    }

    // Also drop any in-flight resolve for this service so the listener
    // can't fire a stale onServiceResolved after we've already reported
    // the peer as gone (TOCTOU between lost and resolved).
    inFlightResolves.remove(serviceName)

    // Derive the same peer-id that onServiceResolved would have used,
    // so the upper layer can match by peer-id.
    val cachedAttributes = removed?.attributes
    val cachedPeerId = cachedAttributes?.get("peer-id")?.let { String(it, Charsets.UTF_8) }
        ?: cachedAttributes?.get("p2p")?.let { String(it, Charsets.UTF_8) }
    val peerId = if (!cachedPeerId.isNullOrBlank()) {
        cachedPeerId
    } else {
        "mdns-$serviceName"
    }
    onPeerDisconnected?.invoke(peerId)
}

fun onServiceRegistered(serviceInfo: NsdServiceInfo) {
    isRegistered = true
    registrationRetryCount = 0
    Timber.i("mDNS service registered: ${serviceInfo.serviceName}")
}

fun onServiceResolved(resolvedInfo: NsdServiceInfo) {
    // Host is deprecated in API 33; use hostAddresses instead
    val hostAddress = if (Build.VERSION.SDK_INT >= Build.VERSION_CODES.UPSIDE_DOWN_CAKE) {
        resolvedInfo.hostAddresses.firstOrNull()?.hostAddress
    } else {
        resolvedInfo.host?.hostAddress
    }
    Timber.d("mDNS service resolved: ${resolvedInfo.serviceName} at ${hostAddress ?: "unknown"}:${resolvedInfo.port}")

    // Skip loopback addresses (127.0.0.1) — these are the device discovering
    // itself and are useless for LAN communication.
    if (hostAddress != null && (hostAddress == "127.0.0.1" || hostAddress == "::1" || hostAddress.startsWith("fe80:"))) {
        Timber.d("mDNS: Skipping loopback/link-local address for ${resolvedInfo.serviceName}: $hostAddress")
        return
    }

    // Track the resolved peer
    discoveredPeers[resolvedInfo.serviceName] = resolvedInfo

    // Extract TXT record attributes (libp2p-mdns may embed peer-id/multiaddr here)
    val txtAttributes = resolvedInfo.attributes
    val txtMap = mutableMapOf<String, String>()
    if (txtAttributes != null) {
        for ((key, value) in txtAttributes) {
            txtMap[key] = String(value, Charsets.UTF_8)
        }
    }
    Timber.d("mDNS TXT records for ${resolvedInfo.serviceName}: $txtMap")

    // Try to extract libp2p peer-id from TXT records
    val libp2pPeerId = txtMap["peer-id"] ?: txtMap["p2p"]

    // Create a peer ID. Prefer the TXT-embedded peer-id;
    // fall back to deriving from the DNS-SD instance name.
    val peerId = if (!libp2pPeerId.isNullOrBlank()) {
        libp2pPeerId
    } else {
        "mdns-${resolvedInfo.serviceName}"
    }

    // Self-loopback guard: NsdManager can hand back this device's own
    // service broadcast as a "discovered" peer. Filter it before it
    // reaches onPeerDiscovered/onLanPeerResolved/SwarmBridge dial.
    val localPeerId = getLocalPeerId?.invoke()
    if (localPeerId != null && peerId == localPeerId) {
        Timber.d("mDNS: ignoring self-resolved service for $peerId")
        return
    }

    // Notify discovery
    onPeerDiscovered(peerId)

    // Build LAN address for SwarmBridge dial:
    // Extract host from resolved service (API-level aware)
    // host is deprecated in API 33; use hostAddresses instead
    val host = if (Build.VERSION.SDK_INT >= Build.VERSION_CODES.UPSIDE_DOWN_CAKE) {
        resolvedInfo.hostAddresses.firstOrNull()?.hostAddress
    } else {
        resolvedInfo.host?.hostAddress
    }
    val port = resolvedInfo.port

    if (host != null && port > 0) {
        // Reconstruct a libp2p multiaddr from resolved IP:port + optional TXT peer-id.
        // Format: /ip4/<host>/tcp/<port>[/p2p/<peerId>]
        val multiaddr = if (!libp2pPeerId.isNullOrBlank()) {
            "/ip4/$host/tcp/$port/p2p/$libp2pPeerId"
        } else {
            "/ip4/$host/tcp/$port"
        }
        Timber.i("mDNS: LAN peer resolved $peerId -> $multiaddr -- notifying for SwarmBridge dial")
        onLanPeerResolved?.invoke(peerId, host, port)
    }
}

fun onServiceUnregistered(serviceInfo: NsdServiceInfo) {
    isRegistered = false
    Timber.i("mDNS service unregistered: ${serviceInfo.serviceName}")
}

fun onStartDiscoveryFailed(serviceType: String, errorCode: Int) {
    isDiscovering = false
    discoveryRetryCount++
    Timber.e("mDNS discovery start failed: type=$serviceType errorCode=$errorCode (retry=$discoveryRetryCount/$maxRetries)")

    // Error code 4 = FAILURE_ALREADY_ACTIVE: discovery is already running
    // from a previous attempt. Stop it first before retrying.
    if (errorCode == 4) {
        Timber.w("mDNS: Discovery already active, stopping before retry")
        try {
            discoveryListener?.let { nsdManager?.stopServiceDiscovery(it) }
        } catch (e: Exception) {
            Timber.w(e, "mDNS: Failed to stop stale discovery")
        }
        isDiscovering = false
    }

    if (discoveryRetryCount <= maxRetries) {
        val backoffMs = 1000L * (1L shl (discoveryRetryCount - 1)) // 1s, 2s, 4s
        handler.postDelayed({
            if (isRunning && !isDiscovering) {
                Timber.d("Retrying mDNS discovery after start failure (attempt $discoveryRetryCount)")
                startDiscovery()
            }
        }, backoffMs)
    } else {
        Timber.e("mDNS discovery start failed after $maxRetries retries -- giving up")
    }
}

fun onStopDiscoveryFailed(serviceType: String, errorCode: Int) {
    isDiscovering = false
    Timber.e("mDNS discovery stop failed: type=$serviceType errorCode=$errorCode")

    // Reset discovering state so we can retry if needed
    if (isRunning) {
        handler.postDelayed({
            Timber.d("Attempting to restart mDNS discovery after stop failure")
            startDiscovery()
        }, 1000)
    }
}

fun onRegistrationFailed(serviceInfo: NsdServiceInfo, errorCode: Int) {
    isRegistered = false
    registrationRetryCount++
    Timber.e("mDNS service registration failed: ${serviceInfo.serviceName} errorCode=$errorCode (retry=$registrationRetryCount/$maxRetries)")

    // Error code 4 = FAILURE_ALREADY_ACTIVE: NsdManager has a stale registration
    // from a previous session. Unregister it and retry ONCE, then fall through
    // to normal retry logic (which has maxRetries cap).
    if (errorCode == 4 && registrationRetryCount <= 2) {
        Timber.w("mDNS: Service already active (errorCode=4), force-unregistering stale registration")
        try {
            registrationListener?.let { nsdManager?.unregisterService(it) }
        } catch (e: Exception) {
            Timber.w(e, "mDNS: Failed to unregister stale service")
        }
        isRegistered = false
        // Retry once after short delay, then fall through to normal retry path
        handler.postDelayed({
            if (isRunning && !isRegistered) {
                Timber.d("mDNS: Retrying registration after stale-unregister cleanup")
                registerService()
            }
        }, 500)
        return
    }
    // For error code 4 beyond 2 attempts, or other errors: fall through to
    // normal retry with exponential backoff and maxRetries cap.
    // If error code 4 persists after cleanup, the NsdManager is stuck —
    // give up gracefully rather than spinning forever.
    if (errorCode == 4 && registrationRetryCount > 2) {
        Timber.e("mDNS: errorCode=4 persists after stale-unregister — giving up mDNS registration")
        return
    }

    if (registrationRetryCount <= maxRetries) {
        val backoffMs = 1000L * (1L shl (registrationRetryCount - 1))
        handler.postDelayed({
            if (isRunning && !isRegistered) {
                Timber.d("Retrying mDNS service registration (attempt $registrationRetryCount)")
                registerService()
            }
        }, backoffMs)
    } else {
        Timber.e("mDNS service registration failed after $maxRetries retries -- giving up")
    }
}

fun onResolveFailed(serviceInfo: NsdServiceInfo, errorCode: Int) {
    Timber.e("mDNS service resolve failed: ${serviceInfo.serviceName} errorCode=$errorCode")

    // Resolution failure is non-critical; the peer will be re-discovered
    // in the next discovery cycle if still present on the network.
}

fun onUnregistrationFailed(serviceInfo: NsdServiceInfo, errorCode: Int) {
    Timber.e("mDNS service unregistration failed: ${serviceInfo.serviceName} errorCode=$errorCode")

    // Force reset registration state to avoid stuck state
    isRegistered = false
}

fun start() {
    if (isRunning) {
        Timber.w("mDNS service discovery already running")
        return
    }

    try {
        val wifiManager = context.applicationContext.getSystemService(Context.WIFI_SERVICE) as? android.net.wifi.WifiManager
        if (wifiManager != null) {
            multicastLock = wifiManager.createMulticastLock("scmessenger_mdns_lock").apply {
                setReferenceCounted(true)
                acquire()
            }
            Timber.i("mDNS Wifi MulticastLock acquired")
        }
    } catch (e: Exception) {
        Timber.w("Failed to acquire Wifi MulticastLock: ${e.message}")
    }

    try {
        nsdManager = context.getSystemService(Context.NSD_SERVICE) as? NsdManager
        if (nsdManager == null) {
            Timber.e("NsdManager not available")
            return
        }

        isRunning = true

        // P0: Force-unregister any stale registration from a previous app session
        // before registering fresh. NsdManager holds registrations across app
        // restarts — without this, the first registerService() fails with
        // errorCode=4 (FAILURE_ALREADY_ACTIVE).
        try {
            // Create a temporary listener to unregister any stale service
            val staleListener = object : NsdManager.RegistrationListener {
                override fun onServiceRegistered(info: NsdServiceInfo) {}
                override fun onRegistrationFailed(info: NsdServiceInfo, code: Int) {}
                override fun onServiceUnregistered(info: NsdServiceInfo) {
                    Timber.d("mDNS: Stale service unregistered successfully")
                }
                override fun onUnregistrationFailed(info: NsdServiceInfo, code: Int) {
                    Timber.d("mDNS: Stale service unregistration not needed (code=$code)")
                }
            }
            val staleInfo = NsdServiceInfo().apply {
                serviceName = getLocalPeerId?.invoke() ?: serviceName
                serviceType = this@MdnsServiceDiscovery.serviceType
                port = servicePort
            }
            nsdManager?.unregisterService(staleListener)
            Timber.d("mDNS: Attempted stale-registration cleanup before fresh register")
        } catch (e: Exception) {
            Timber.d("mDNS: Stale cleanup skipped (no prior registration): ${e.message}")
        }

        // Register our service
        registerService()

        // Start discovering other services
        startDiscovery()

        Timber.i("mDNS service discovery started")
    } catch (e: SecurityException) {
        Timber.e(e, "Security exception starting mDNS service discovery")
    } catch (e: Exception) {
        Timber.e(e, "Failed to start mDNS service discovery")
    }
}

fun stop() {
    if (!isRunning) {
        return
    }

    isRunning = false

    try {
        multicastLock?.let {
            if (it.isHeld) {
                it.release()
                Timber.i("mDNS Wifi MulticastLock released")
            }
        }
        multicastLock = null
    } catch (e: Exception) {
        Timber.w("Failed to release Wifi MulticastLock: ${e.message}")
    }

    try {
        // Stop discovery
        if (isDiscovering) {
            discoveryListener?.let { nsdManager?.stopServiceDiscovery(it) }
            isDiscovering = false
        }

        // Unregister service
        if (isRegistered) {
            registrationListener?.let { nsdManager?.unregisterService(it) }
            isRegistered = false
        }

        discoveredPeers.clear()
        // P0_ANDROID_025: clear any in-flight resolves so listeners held by
        // NsdManager don't get a callback after we stop. The in-flight set
        // would otherwise leak a few entries on stop-while-resolving, which
        // is harmless (the listener self-removes on next callback) but tidy.
        inFlightResolves.clear()
        Timber.i("mDNS service discovery stopped")
    } catch (e: SecurityException) {
        Timber.e(e, "Security exception stopping mDNS service discovery")
    } catch (e: Exception) {
        Timber.e(e, "Failed to stop mDNS service discovery")
    }
}

private fun registerService() {
    val localId = getLocalPeerId?.invoke()
    val serviceInfo = NsdServiceInfo().apply {
        serviceName = if (!localId.isNullOrBlank()) localId else this@MdnsServiceDiscovery.serviceName
        serviceType = this@MdnsServiceDiscovery.serviceType
        port = servicePort
        // Add service data to identify this as an SCMessenger device
        setAttribute("version", "1.0")
        setAttribute("service", "scmessenger")

        // Set peer ID attributes so other peers (like Windows CLI) can discover us and associate our IP with our peer ID
        if (!localId.isNullOrBlank()) {
            setAttribute("peer-id", localId)
            setAttribute("p2p", localId)
            setAttribute("dnsaddr", "/ip4/0.0.0.0/tcp/$servicePort/p2p/$localId")
            Timber.i("mDNS advertising TXT peer-id: $localId")
        }
    }

    registrationListener = object : NsdManager.RegistrationListener {
        override fun onRegistrationFailed(serviceInfo: NsdServiceInfo, errorCode: Int) {
            this@MdnsServiceDiscovery.onRegistrationFailed(serviceInfo, errorCode)
        }

        override fun onUnregistrationFailed(serviceInfo: NsdServiceInfo, errorCode: Int) {
            this@MdnsServiceDiscovery.onUnregistrationFailed(serviceInfo, errorCode)
        }

        override fun onServiceRegistered(serviceInfo: NsdServiceInfo) {
            this@MdnsServiceDiscovery.onServiceRegistered(serviceInfo)
        }

        override fun onServiceUnregistered(serviceInfo: NsdServiceInfo) {
            this@MdnsServiceDiscovery.onServiceUnregistered(serviceInfo)
        }
    }

    nsdManager?.registerService(serviceInfo, NsdManager.PROTOCOL_DNS_SD, registrationListener)
}

private fun startDiscovery() {
    discoveryListener = object : NsdManager.DiscoveryListener {
        override fun onDiscoveryStarted(regType: String) {
            this@MdnsServiceDiscovery.onDiscoveryStarted(regType)
        }

        override fun onDiscoveryStopped(regType: String) {
            this@MdnsServiceDiscovery.onDiscoveryStopped(regType)
        }

        override fun onServiceFound(serviceInfo: NsdServiceInfo) {
            this@MdnsServiceDiscovery.onServiceFound(serviceInfo)
        }

        override fun onServiceLost(serviceInfo: NsdServiceInfo) {
            this@MdnsServiceDiscovery.onServiceLost(serviceInfo)
        }

        override fun onStartDiscoveryFailed(serviceType: String, errorCode: Int) {
            this@MdnsServiceDiscovery.onStartDiscoveryFailed(serviceType, errorCode)
        }

        override fun onStopDiscoveryFailed(serviceType: String, errorCode: Int) {
            this@MdnsServiceDiscovery.onStopDiscoveryFailed(serviceType, errorCode)
        }
    }

    nsdManager?.discoverServices(serviceType, NsdManager.PROTOCOL_DNS_SD, discoveryListener)
}

private fun resolveService(serviceInfo: NsdServiceInfo) {
    // P0_ANDROID_025: NsdManager rejects reusing the same ResolveListener
    // while a previous resolve is in flight. Create a fresh listener per
    // call and track it in `inFlightResolves` so we never reuse one, and
    // the listener's terminal callbacks will self-remove from the set.

    val serviceName = serviceInfo.serviceName
    if (inFlightResolves.containsKey(serviceName)) {
        Timber.d("mDNS resolve already in flight for $serviceName, skipping redundant call")
        return
    }

    val listener = newResolveListener(serviceName)
    // Double-check with putIfAbsent to avoid race between containsKey and put
    if (inFlightResolves.putIfAbsent(serviceName, listener) != null) {
        Timber.d("mDNS resolve just started by another thread for $serviceName, skipping")
        return
    }

    // P0: NsdManager.resolveService with Executor was added in API 34 (Android 14).
    // The Listener-only signature was deprecated in API 33 but is the ONLY option on
    // API 26-33. We previously gated on API 28 (P) which is wrong — on API 28-33
    // there is no `resolveService(NsdServiceInfo, Executor, ResolveListener)` method,
    // so the call throws NoSuchMethodError and crashes the process when an mDNS service
    // is discovered. The fix: use the Executor overload only on API 34+ and fall back
    // to the legacy single-arg signature on API 26-33. See lines 183, 220 for the same
    // pattern applied to NsdServiceInfo.host getter.
    if (Build.VERSION.SDK_INT >= Build.VERSION_CODES.UPSIDE_DOWN_CAKE) {
        // API 34+ has the Executor overload, use it to avoid the deprecation warning
        nsdManager?.resolveService(serviceInfo, context.getMainExecutor(), listener)
    } else {
        // Legacy API for API 26-33. Listener-only signature still works on these
        // versions; the Executor overload was only added in API 34.
        @Suppress("DEPRECATION")
        nsdManager?.resolveService(serviceInfo, listener)
    }
}

fun cleanup() {
    stop()
}

fun startMonitoring() {
    if (networkCallback != null) {
        Timber.d("NetworkDetector already monitoring")
        return
    }

    // Registration must never abort the caller: some OEM ConnectivityManager
    // implementations throw (SecurityException, TooManyRequestsException),
    // and JVM unit tests stub the framework classes entirely. The mesh
    // degrades to no cellular-awareness, which is safe.
    try {
        startMonitoringInternal()
    } catch (e: Exception) {
        Timber.w(e, "NetworkDetector monitoring unavailable; continuing without it")
    }
}

private fun startMonitoringInternal() {
    val request = NetworkRequest.Builder()
        .addCapability(NetworkCapabilities.NET_CAPABILITY_INTERNET)
        .build()

    val callback = object : ConnectivityManager.NetworkCallback() {
        override fun onAvailable(network: Network) {
            scheduleNetworkRedetection()
        }

        override fun onLost(network: Network) {
            networkCapabilities.remove(network)
            Timber.d("Network lost: %s", network)
            scheduleNetworkRedetection()
        }

        override fun onCapabilitiesChanged(
            network: Network,
            capabilities: NetworkCapabilities
        ) {
            networkCapabilities[network] = capabilities
            scheduleNetworkRedetection()
        }
    }

    connectivityManager.registerNetworkCallback(request, callback)
    networkCallback = callback

    // Detect current network with debounce
    scheduleNetworkRedetection()

    Timber.i("NetworkDetector monitoring started")
}

fun stopMonitoring() {
    networkCallback?.let {
        connectivityManager.unregisterNetworkCallback(it)
    }
    networkCallback = null
    debounceJob?.cancel()
    debounceJob = null
    Timber.i("NetworkDetector monitoring stopped")
}

private fun scheduleNetworkRedetection() {
    Timber.d("Network change detected, scheduling redetection with %dms debounce", networkStabilityMs)

    debounceJob?.cancel()
    debounceJob = debounceScope.launch {
        delay(networkStabilityMs)
        redetectCurrentNetworkLocked()
    }
}

private fun redetectCurrentNetworkLocked() {
    val activeNetwork = connectivityManager.activeNetwork
    if (activeNetwork != null) {
        val capabilities = connectivityManager.getNetworkCapabilities(activeNetwork)
        if (capabilities != null) {
            val type = classifyNetworkType(capabilities)
            updateNetworkType(type)
        }
    } else {
        _networkType.value = NetworkType.UNKNOWN
        _blockedPorts.value = emptySet()
    }
}

private fun updateNetworkType(newType: NetworkType) {
    val previousType = _networkType.value
    _networkType.value = newType

    if (newType == NetworkType.CELLULAR || newType == NetworkType.CELLULAR_RESTRICTED) {
        _blockedPorts.value = commonlyBlockedPorts
        Timber.w("Cellular network detected (%s) after %dms stability — blocking ports: %s",
            newType, networkStabilityMs, commonlyBlockedPorts)
    } else {
        _blockedPorts.value = emptySet()
    }

    Timber.i("Network type updated: %s → %s (stable for %dms), blocked ports: %s",
        previousType, newType, networkStabilityMs, _blockedPorts.value)
}

private fun classifyNetworkType(capabilities: NetworkCapabilities): NetworkType {
    return when {
        capabilities.hasTransport(NetworkCapabilities.TRANSPORT_WIFI) -> {
            if (!capabilities.hasCapability(NetworkCapabilities.NET_CAPABILITY_VALIDATED)) {
                NetworkType.WIFI_RESTRICTED
            } else {
                NetworkType.WIFI
            }
        }
        capabilities.hasTransport(NetworkCapabilities.TRANSPORT_CELLULAR) -> {
            when {
                !capabilities.hasCapability(NetworkCapabilities.NET_CAPABILITY_INTERNET) ->
                    NetworkType.CELLULAR_NO_INTERNET
                !capabilities.hasCapability(NetworkCapabilities.NET_CAPABILITY_VALIDATED) ->
                    NetworkType.CELLULAR_RESTRICTED
                else -> NetworkType.CELLULAR
            }
        }
        capabilities.hasTransport(NetworkCapabilities.TRANSPORT_ETHERNET) -> NetworkType.ETHERNET
        capabilities.hasTransport(NetworkCapabilities.TRANSPORT_BLUETOOTH) -> NetworkType.BLUETOOTH
        capabilities.hasTransport(NetworkCapabilities.TRANSPORT_VPN) -> NetworkType.VPN
        else -> NetworkType.UNKNOWN
    }
}

fun isPortLikelyBlocked(port: Int): Boolean {
    // On cellular, non-standard ports are commonly blocked
    return isCellularNetwork && port !in allowedStandardPorts
}

fun getTransportPriority(): List<FallbackTransport> {
    return when (_networkType.value) {
        NetworkType.WIFI, NetworkType.ETHERNET -> listOf(
            FallbackTransport.QUIC,
            FallbackTransport.TCP,
            FallbackTransport.WEBSOCKET_WSS,
            FallbackTransport.WEBSOCKET_WS,
        )
        NetworkType.CELLULAR -> listOf(
            // On cellular, prefer WebSocket on standard ports first
            FallbackTransport.WEBSOCKET_WSS,
            FallbackTransport.TCP_STANDARD,
            FallbackTransport.QUIC,
            FallbackTransport.TCP,
            FallbackTransport.WEBSOCKET_WS,
        )
        // Restricted networks: prioritize standard-port transports
        NetworkType.CELLULAR_RESTRICTED, NetworkType.WIFI_RESTRICTED -> listOf(
            FallbackTransport.WEBSOCKET_WSS,
            FallbackTransport.TCP_STANDARD,
            FallbackTransport.WEBSOCKET_WS,
            FallbackTransport.QUIC,
            FallbackTransport.TCP,
        )
        NetworkType.CELLULAR_NO_INTERNET -> listOf(
            // No internet: only mDNS/BLE local transports will work
            FallbackTransport.WEBSOCKET_WSS,
            FallbackTransport.TCP_STANDARD,
        )
        NetworkType.BLUETOOTH, NetworkType.VPN -> listOf(
            FallbackTransport.WEBSOCKET_WSS,
            FallbackTransport.QUIC,
            FallbackTransport.TCP,
        )
        NetworkType.UNKNOWN -> listOf(
            FallbackTransport.WEBSOCKET_WSS,
            FallbackTransport.QUIC,
            FallbackTransport.TCP,
        )
    }
}

fun getNetworkDiagnostics(): NetworkDiagnostics {
    val activeNetwork = connectivityManager.activeNetwork
    val capabilities = activeNetwork?.let {
        connectivityManager.getNetworkCapabilities(it)
    }

    return NetworkDiagnostics(
        networkType = _networkType.value,
        blockedPorts = _blockedPorts.value,
        hasInternet = capabilities?.hasCapability(NetworkCapabilities.NET_CAPABILITY_INTERNET) ?: false,
        hasValidated = capabilities?.hasCapability(NetworkCapabilities.NET_CAPABILITY_VALIDATED) ?: false,
        isMetered = !(
            capabilities?.hasCapability(NetworkCapabilities.NET_CAPABILITY_NOT_METERED) ?: false
        ),
        upstreamBandwidth = capabilities?.linkUpstreamBandwidthKbps ?: 0,
        downstreamBandwidth = capabilities?.linkDownstreamBandwidthKbps ?: 0,
        recommendedTransports = getTransportPriority()
    )
}

fun fromValue(value: String): TransportType? {
    return entries.find { it.value == value }
}

suspend fun recordSuccess(peerId: String, transport: TransportType, latencyMs: Long) {
    healthMutex.withLock {
        val health = getHealth(peerId, transport)
        health.lastSuccessAt = System.currentTimeMillis()
        health.successCount++
        health.lastLatencyMs = latencyMs

        // Update rolling average latency
        val totalDeliveries = health.successCount + health.failureCount
        health.averageLatencyMs = if (totalDeliveries > 1) {
            ((health.averageLatencyMs * (totalDeliveries - 1)) + latencyMs) / totalDeliveries
        } else {
            latencyMs.toDouble()
        }

        setHealth(peerId, transport, health)
        lastSuccessfulTransport[peerId] = transport

        Timber.tag(TAG).i("Transport health updated: peer=${peerId.take(8)} transport=${transport.value} success_rate=${String.format("%.2f", health.successRate)} avg_latency=${String.format("%.0f", health.averageLatencyMs)}ms")
    }
}

suspend fun recordFailure(peerId: String, transport: TransportType, error: String?) {
    healthMutex.withLock {
        val health = getHealth(peerId, transport)
        health.lastFailureAt = System.currentTimeMillis()
        health.failureCount++

        setHealth(peerId, transport, health)

        Timber.tag(TAG).w("Transport failure: peer=${peerId.take(8)} transport=${transport.value} error=${error ?: "unknown"} success_rate=${String.format("%.2f", health.successRate)}")
    }
}

private fun getHealth(peerId: String, transport: TransportType): TransportHealth {
    return transportHealth.getOrPut(peerId) { ConcurrentHashMap() }
        .getOrPut(transport) { TransportHealth() }
}

private fun setHealth(peerId: String, transport: TransportType, health: TransportHealth) {
    transportHealth.getOrPut(peerId) { ConcurrentHashMap() }[transport] = health
}

fun getPreferredTransport(peerId: String): TransportType? {
    // First check if we have a last successful transport
    val lastSuccess = lastSuccessfulTransport[peerId]
    if (lastSuccess != null) {
        val health = getHealth(peerId, lastSuccess)
        if (health.isHealthy) {
            return lastSuccess
        }
    }

    // Otherwise, find the transport with the highest score
    var bestTransport: TransportType? = null
    var bestScore = -1.0

    for (transport in TransportType.entries) {
        val health = getHealth(peerId, transport)
        if (health.score > bestScore) {
            bestScore = health.score
            bestTransport = transport
        }
    }

    return bestTransport
}

fun getAvailableTransportsSorted(peerId: String): List<TransportType> {
    return TransportType.entries.sortedByDescending { transport ->
        getHealth(peerId, transport).score
    }
}

fun getAvailableTransports(peerId: String): List<TransportType> {
    val peerTransports = transportHealth[peerId]
    return if (peerTransports != null && peerTransports.isNotEmpty()) {
        // Return transports that have health data (indicating they've been used)
        peerTransports.keys.toList()
    } else {
        // No health data yet — return all transport types as potentially available
        TransportType.entries
    }
}

fun getDedupStats(messageId: String): MessageDedupEntry? {
    return messageDedupCache[messageId]
}

private fun cleanupDedupCache() {
    val cutoff = System.currentTimeMillis() - DEDUP_CACHE_TTL_MS
    messageDedupCache.entries.removeIf { (_, entry) ->
        entry.firstReceivedAt < cutoff
    }
}

fun getHealthSummary(): Map<String, Map<String, Any>> {
    val summary = mutableMapOf<String, Map<String, Any>>()

    for ((peerId, transports) in transportHealth) {
        val peerSummary = mutableMapOf<String, Any>()
        for ((transport, health) in transports) {
            peerSummary[transport.value] = mapOf(
                "success_rate" to health.successRate,
                "avg_latency_ms" to health.averageLatencyMs,
                "success_count" to health.successCount,
                "failure_count" to health.failureCount,
                "is_healthy" to health.isHealthy,
                "score" to health.score
            )
        }
        summary[peerId] = peerSummary
    }

    return summary
}

fun resetHealth(peerId: String) {
    transportHealth.remove(peerId)
    lastSuccessfulTransport.remove(peerId)
    Timber.tag(TAG).i("Transport health reset for peer ${peerId.take(8)}")
}

fun start() {
    if (isRunning) {
        Timber.d("SubnetProbe already running; start() ignored")
        return
    }
    isRunning = true
    Timber.i("SubnetProbe starting (interval=${scanIntervalMs}ms, ports=${targetPorts.toList()})")
    sweepJob = scope.launch {
        // Run an immediate first sweep, then loop on the interval.
        while (isRunning) {
            try {
                runSweep()
            } catch (t: Throwable) {
                Timber.w(t, "SubnetProbe sweep failed")
            }
            if (!isRunning) break
            delay(scanIntervalMs)
        }
    }
}

fun cleanup() {
    stop()
    scope.cancel()
}

private suspend fun runSweep() {
    val localSelfIps = enumerateLocalIPv4Addresses()
    val subnets = enumerateCandidateSubnets()
    if (subnets.isEmpty()) {
        Timber.d("SubnetProbe: no candidate subnets (no WiFi/Ethernet link?)")
        return
    }
    Timber.d("SubnetProbe: scanning ${subnets.size} subnets, skipping self=$localSelfIps")

    val candidates = mutableListOf<Pair<String, Int>>()
    for (subnet in subnets) {
        // Avoid re-scanning the same /24 within the dedup window.
        if (probedSubnetsThisCycle[subnet]?.let { (System.currentTimeMillis() - it) < reportDedupMs } == true) {
            continue
        }
        probedSubnetsThisCycle[subnet] = System.currentTimeMillis()
        candidates += expandSubnet(subnet)
    }

    // Fan out probes in bounded parallel batches. The semaphore is the
    // kotlinx.coroutines suspending variant: waiting coroutines suspend
    // instead of parking Dispatchers.IO threads. (The previous
    // java.util.concurrent.Semaphore froze the entire IO pool — thousands
    // of coroutines each blocking a real thread in acquire() — which
    // starved all other background work and fired an ANR on "Rescan".)
    val sem = Semaphore(maxConcurrentProbes)
    val jobs = candidates.map { (host, port) ->
        scope.async {
            sem.withPermit {
                if (!isRunning) return@withPermit
                if (host in localSelfIps) return@withPermit
                probeHost(host, port, localSelfIps)
            }
        }
    }
    jobs.awaitAll()
}

private suspend fun probeHost(host: String, port: Int, localSelfIps: Set<String>) {
    if (host in localSelfIps) return
    val key = "$host:$port"
    val now = System.currentTimeMillis()
    recentlyReported.entries.removeAll { (_, ts) -> (now - ts) > reportDedupMs }
    if (recentlyReported.containsKey(key)) return

    // Non-blocking connect: AsynchronousSocketChannel completes on its own
    // small NIO group instead of parking an IO-dispatcher thread per probe.
    // A connect that is accepted is a sufficient liveness signal — we no
    // longer peek-read a byte, which used to hold the socket (and a
    // thread) open for up to another 200ms per host.
    val opened = withTimeoutOrNull(connectTimeoutMs.toLong() + 250L) {
        connectAsync(host, port)
    } ?: false

    if (!opened) return

    recentlyReported[key] = now
    // Port 9002 is a WebSocket listener — append /ws so libp2p uses the
    // correct transport. Port 9001 is raw TCP.
    val multiaddr = if (port == 9002) "/ip4/$host/tcp/$port/ws" else "/ip4/$host/tcp/$port"
    Timber.i("SubnetProbe: open port $host:$port (likely SCMessenger peer) -> $multiaddr")
    // Let the probe socket's TIME_WAIT state clear on the peer before the
    // dialer opens the real libp2p connection to the same ip:port.
    if (dialDelayMs > 0) delay(dialDelayMs)
    try {
        onLanAddressResolved(multiaddr, TransportType.TCP_MDNS)
    } catch (t: Throwable) {
        Timber.w(t, "SubnetProbe: onLanAddressResolved callback threw")
    }
}

private suspend fun connectAsync(host: String, port: Int): Boolean =
    suspendCancellableCoroutine { cont ->
        val channel = try {
            AsynchronousSocketChannel.open()
        } catch (t: Throwable) {
            cont.resume(false)
            return@suspendCancellableCoroutine
        }
        cont.invokeOnCancellation {
            try { channel.close() } catch (_: Throwable) {}
        }
        try {
            channel.connect(
                InetSocketAddress(host, port),
                Unit,
                object : CompletionHandler<Void?, Unit> {
                    override fun completed(result: Void?, attachment: Unit) {
                        try { channel.close() } catch (_: Throwable) {}
                        if (cont.isActive) cont.resume(true)
                    }

                    override fun failed(exc: Throwable, attachment: Unit) {
                        try { channel.close() } catch (_: Throwable) {}
                        if (cont.isActive) cont.resume(false)
                    }
                }
            )
        } catch (t: Throwable) {
            try { channel.close() } catch (_: Throwable) {}
            if (cont.isActive) cont.resume(false)
        }
    }

private fun enumerateLocalIPv4Addresses(): Set<String> {
    val result = HashSet<String>()
    try {
        val cm = context.applicationContext.getSystemService(Context.CONNECTIVITY_SERVICE) as? ConnectivityManager
            ?: return result
        val active = cm.activeNetwork ?: return result
        val link: LinkProperties = cm.getLinkProperties(active) ?: return result
        for (addr in link.linkAddresses) {
            val ip = addr.address
            if (ip is Inet4Address && !ip.isLoopbackAddress) {
                result += ip.hostAddress.orEmpty()
            }
        }
    } catch (t: Throwable) {
        Timber.w(t, "SubnetProbe: failed to enumerate local IPv4 addresses")
    }
    return result
}

private fun enumerateCandidateSubnets(): List<String> {
    val out = LinkedHashSet<String>()
    try {
        val cm = context.applicationContext.getSystemService(Context.CONNECTIVITY_SERVICE) as? ConnectivityManager
        if (cm != null) {
            val networks = if (Build.VERSION.SDK_INT >= Build.VERSION_CODES.LOLLIPOP) {
                cm.allNetworks
            } else {
                null
            }
            if (networks != null) {
                for (net in networks) {
                    val caps = cm.getNetworkCapabilities(net) ?: continue
                    // Only scan interfaces that are useful for LAN discovery.
                    if (!caps.hasTransport(NetworkCapabilities.TRANSPORT_WIFI) &&
                        !caps.hasTransport(NetworkCapabilities.TRANSPORT_ETHERNET) &&
                        !caps.hasTransport(NetworkCapabilities.TRANSPORT_VPN)) {
                        continue
                    }
                    val link = cm.getLinkProperties(net) ?: continue
                    for (addr in link.linkAddresses) {
                        val ip = addr.address
                        if (ip !is Inet4Address || ip.isLoopbackAddress) continue
                        out += narrowToScanSubnet(addr)
                    }
                }
            } else {
                // Legacy fallback (< API 21) — should not happen on minSdk 26.
                val link = cm.activeNetwork?.let { cm.getLinkProperties(it) }
                if (link != null) {
                    for (addr in link.linkAddresses) {
                        val ip = addr.address
                        if (ip !is Inet4Address || ip.isLoopbackAddress) continue
                        out += narrowToScanSubnet(addr)
                    }
                }
            }
        }
    } catch (t: Throwable) {
        Timber.w(t, "SubnetProbe: failed to enumerate candidate subnets")
    }

    // Always probe a few common defaults in case the device's own
    // interface is misreported (e.g. mobile hotspot on a different /24
    // than the host that runs the daemon).
    for (fallback in FALLBACK_SUBNETS) {
        out += fallback
    }
    return out.toList()
}

private fun narrowToScanSubnet(addr: LinkAddress): String {
    val ip = addr.address as Inet4Address
    val rawPrefix = addr.prefixLength
    val octets = ip.hostAddress.split(".")
    if (octets.size != 4) return "${octets[0]}.${octets[1]}.${octets[2]}.0/24"
    return when {
        // Use /24 around the local host for the typical /16 home LAN.
        rawPrefix < 24 -> "${octets[0]}.${octets[1]}.${octets[2]}.0/24"
        // /30 or smaller — scan the whole thing.
        else -> {
            val mask = ipv4NetmaskInt(rawPrefix)
            val ipInt = (octets[0].toInt() and 0xff shl 24) or
                (octets[1].toInt() and 0xff shl 16) or
                (octets[2].toInt() and 0xff shl 8) or
                (octets[3].toInt() and 0xff)
            val netInt = ipInt and mask
            val a = (netInt ushr 24) and 0xff
            val b = (netInt ushr 16) and 0xff
            val c = (netInt ushr 8) and 0xff
            val d = netInt and 0xff
            "$a.$b.$c.$d/$rawPrefix"
        }
    }
}

private fun ipv4NetmaskInt(prefixLen: Int): Int {
    if (prefixLen <= 0) return 0
    if (prefixLen >= 32) return -1 // 0xFFFFFFFF
    return (0xFFFFFFFF.toInt() shl (32 - prefixLen))
}

private fun expandSubnet(subnet: String): List<Pair<String, Int>> {
    val parts = subnet.split("/")
    val base = parts[0]
    val prefix = parts.getOrNull(1)?.toIntOrNull() ?: 24
    val octets = base.split(".")
    if (octets.size != 4) return emptyList()
    val a = octets[0].toIntOrNull() ?: return emptyList()
    val b = octets[1].toIntOrNull() ?: return emptyList()
    val c = octets[2].toIntOrNull() ?: return emptyList()
    val d = octets[3].toIntOrNull() ?: return emptyList()

    val out = ArrayList<Pair<String, Int>>(256)
    val ips = if (prefix >= 24) {
        (1..254).map { last -> "$a.$b.$c.$last" }
    } else {
        // /16 or wider: only scan the local /24 around the device
        // (i.e. just the .0/24 from the local address). Expanding a /16
        // would mean 65k probes, which is unacceptable.
        (1..254).map { last -> "$a.$b.$c.$last" }
    }
    for (host in ips) {
        for (port in targetPorts) {
            out += host to port
        }
    }
    return out
}

fun recordSuccess(transport: String, latencyMs: Long? = null) {
    val health = transportHealth.getOrPut(transport) { TransportHealth() }
    health.successCount++
    health.consecutiveFailures = 0
    latencyMs?.let { health.totalLatencyMs += it }
    health.lastUpdated = System.currentTimeMillis()
}

fun recordFailure(transport: String) {
    val health = transportHealth.getOrPut(transport) { TransportHealth() }
    health.failureCount++
    health.consecutiveFailures++
    health.lastUpdated = System.currentTimeMillis()

    if (health.consecutiveFailures >= CONSECUTIVE_FAILURE_THRESHOLD) {
        Timber.w("Transport $transport has ${health.consecutiveFailures} consecutive failures")
    }
}

fun getHealth(transport: String): TransportHealth {
    return transportHealth[transport] ?: TransportHealth()
}

fun isDegraded(transport: String): Boolean {
    val health = getHealth(transport)
    return health.consecutiveFailures >= CONSECUTIVE_FAILURE_THRESHOLD
}

fun getSummary(): Map<String, TransportHealth> = transportHealth.toMap()

companion object {
    private const val MIN_SAMPLES = 5
    private const val MIN_SUCCESS_RATE = 0.3
    private const val CONSECUTIVE_FAILURE_THRESHOLD = 3
}

fun startAll(enableMdns: Boolean = true) {
    if (isRunning) {
        Timber.w("TransportManager already running")
        return
    }

    isRunning = true

    // Start BLE
    scope.launch { bleScanner?.startScanning() }
    bleAdvertiser?.startAdvertising()
    bleGattServer?.start()
    bleL2capManager?.startListening()

    // Start WiFi Aware
    wifiAware?.start()

    // Start WiFi Direct
    wifiDirect?.start()

    // Start mDNS LAN discovery (cross-platform: discovers Windows/macOS/iOS peers)
    if (enableMdns) {
        val discovery = getOrCreateMdns()
        discovery.start()
        // Also start the TCP subnet probe as a fallback. mDNS multicast
        // is link-local and does NOT cross routers, different broadcast
        // domains, or WSL-style virtual NICs. The probe sends unicast
        // TCP connect attempts to common /24 subnets on port 9001/9002
        // and feeds any open host into SwarmBridge.
        val probe = getOrCreateSubnetProbe()
        probe.start()
        Timber.i("All transports started (including mDNS LAN discovery + TCP subnet probe)")
    } else {
        Timber.i("All transports started (mDNS/LAN disabled as requested)")
    }
}

private fun getOrCreateMdns(): MdnsServiceDiscovery {
    var mdns = mdnsDiscovery
    if (mdns == null) {
        mdns = MdnsServiceDiscovery(
            context,
            onPeerDiscovered = { peerId ->
                Timber.d("mDNS peer discovered: $peerId")
                activeTransports[TransportType.TCP_MDNS] = true
                onPeerDiscovered(peerId, TransportType.TCP_MDNS)
            },
            onDataReceived = { peerId, data ->
                onDataReceived(peerId, data, TransportType.TCP_MDNS)
            },
            // P1 (Bug 5): propagate mDNS peer loss upward so MeshRepository
            // can prune the peer and emit disconnect events. Previously the
            // upper layer never learned about mDNS-only disconnects.
            onPeerDisconnected = { peerId ->
                Timber.d("mDNS peer disconnected: $peerId")
                activeTransports[TransportType.TCP_MDNS] = activeTransports[TransportType.TCP_MDNS] == true
                this@TransportManager.onPeerDisconnected?.invoke(peerId, TransportType.TCP_MDNS)
            },
            onLanPeerResolved = { peerId, host, port ->
                Timber.i("mDNS LAN peer resolved: $peerId at $host:$port — feeding to SwarmBridge")
                val multiaddr = if (peerId.startsWith("12D3Koo")) {
                    "/ip4/$host/tcp/$port/p2p/$peerId"
                } else {
                    "/ip4/$host/tcp/$port"
                }
                onLanAddressResolved?.invoke(multiaddr)
                onPeerDiscovered(peerId, TransportType.TCP_MDNS)
            },
            getLocalPeerId = getLocalPeerId
        )
        mdnsDiscovery = mdns
    }
    return mdns
}

private fun getOrCreateSubnetProbe(): SubnetProbe {
    var probe = subnetProbe
    if (probe == null) {
        probe = SubnetProbe(
            context = context,
            onLanAddressResolved = { multiaddr, _ ->
                Timber.i("SubnetProbe: LAN address resolved -> $multiaddr — feeding to SwarmBridge")
                onLanAddressResolved?.invoke(multiaddr)
                activeTransports[TransportType.TCP_MDNS] = true
            },
            getLocalPeerId = getLocalPeerId
        )
        subnetProbe = probe
    }
    return probe
}

fun stopAll() {
    if (!isRunning) {
        return
    }

    isRunning = false

    // Stop BLE
    scope.launch { bleScanner?.stopScanning() }
    bleAdvertiser?.stopAdvertising()
    bleGattServer?.stop()
    bleL2capManager?.stopListening()

    // Stop WiFi
    wifiAware?.stop()
    wifiDirect?.stop()

    // Stop mDNS
    mdnsDiscovery?.stop()
    mdnsDiscovery = null

    // Stop TCP subnet probe
    subnetProbe?.stop()
    subnetProbe = null

    activeTransports.clear()
    peerTransports.clear()

    Timber.i("All transports stopped")
}

suspend fun sendData(peerId: String, data: ByteArray): Boolean {
    // Use cached transport if available and healthy
    val preferredTransport = peerTransports[peerId]

    if (preferredTransport != null) {
        // Check health before attempting preferred transport
        if (transportHealthMonitor.shouldUseTransport(preferredTransport.name)) {
            val success = sendViaTransport(peerId, data, preferredTransport)
            if (success) return true
        }
    }

    // Try transports in priority order: WiFi Aware > WiFi Direct > BLE
    // Skip transports that TransportHealthMonitor has marked as degraded
    if (activeTransports[TransportType.WIFI_AWARE] == true && transportHealthMonitor.shouldUseTransport("wifi_aware")) {
        if (sendViaTransport(peerId, data, TransportType.WIFI_AWARE)) {
            peerTransports[peerId] = TransportType.WIFI_AWARE
            return true
        }
    }

    if (activeTransports[TransportType.WIFI_DIRECT] == true && transportHealthMonitor.shouldUseTransport("wifi_direct")) {
        if (sendViaTransport(peerId, data, TransportType.WIFI_DIRECT)) {
            peerTransports[peerId] = TransportType.WIFI_DIRECT
            return true
        }
    }

    if (activeTransports[TransportType.BLE] == true && transportHealthMonitor.shouldUseTransport("ble")) {
        if (sendViaTransport(peerId, data, TransportType.BLE)) {
            peerTransports[peerId] = TransportType.BLE
            return true
        }
    }

    Timber.w("Failed to send data to $peerId via any transport")
    return false
}

private suspend fun sendViaTransport(peerId: String, data: ByteArray, transport: TransportType): Boolean {
    return when (transport) {
        TransportType.BLE -> run {
            // Prefer connected transport channels before non-targeted advertiser payloads.
            if (bleL2capManager?.sendData(peerId, data) == true) {
                return@run true
            }
            if (bleGattClient?.sendData(peerId, data) == true) {
                return@run true
            }
            val gattServer = bleGattServer
            if (gattServer != null) {
                if (gattServer.sendData(peerId, data)) {
                    return@run true
                }
                val connectedDevices = gattServer.getConnectedDeviceAddresses()
                    .filter { address -> address != peerId }
                if (connectedDevices.size == 1 && gattServer.sendData(connectedDevices.first(), data)) {
                    Timber.d(
                        "BLE send fallback via GATT server connected peer ${connectedDevices.first()} (requested=$peerId)"
                    )
                    return@run true
                }
            }
            bleAdvertiser?.sendData(data) ?: false
        }
        TransportType.WIFI_AWARE -> {
            wifiAware?.sendData(peerId, data) ?: false
        }
        TransportType.WIFI_DIRECT -> {
            wifiDirect?.sendData(peerId, data) ?: false
        }
        TransportType.INTERNET -> {
            // Handled by SwarmBridge, not here
            false
        }
        TransportType.TCP_MDNS -> {
            // Handled by SwarmBridge via LAN TCP, not here
            false
        }
    }
}

fun attemptEscalation(peerId: String) {
    scope.launch {
        Timber.d("Attempting transport escalation for $peerId")

        // Try WiFi Aware first
        if (wifiAware?.isAvailable() == true) {
            Timber.d("Escalating $peerId to WiFi Aware")
            // WiFi Aware discovery is automatic, just mark as preferred
            activeTransports[TransportType.WIFI_AWARE] = true
        }

        // Try WiFi Direct as fallback
        if (activeTransports[TransportType.WIFI_DIRECT] != true) {
            Timber.d("Escalating $peerId to WiFi Direct")
            // WiFi Direct will auto-connect when service is discovered
            activeTransports[TransportType.WIFI_DIRECT] = true
        }
    }
}

fun getActiveTransports(): List<TransportType> {
    return activeTransports.filter { it.value }.keys.toList()
}

fun getAvailableTransports(): List<String> {
    val available = mutableListOf<String>()

    if (bleScanner != null || bleAdvertiser != null) {
        available.add("BLE")
    }

    if (wifiAware?.isAvailable() == true) {
        available.add("WiFiAware")
    }

    if (wifiDirect != null) {
        available.add("WiFiDirect")
    }

    return available
}

private fun initializeBle() {
    try {
        // Scanner
        bleScanner = BleScanner(
            context,
            onPeerDiscovered = { peerId ->
                Timber.d("BLE peer discovered: $peerId")
                activeTransports[TransportType.BLE] = true
                onPeerDiscovered(peerId, TransportType.BLE)

                // Attempt escalation to higher transports
                attemptEscalation(peerId)
            },
            onDataReceived = { peerId, data ->
                onDataReceived(peerId, data, TransportType.BLE)
            }
        )

        // Advertiser
        bleAdvertiser = BleAdvertiser(context)

        // GATT Server
        bleGattServer = BleGattServer(context) { peerId, data ->
            onDataReceived(peerId, data, TransportType.BLE)
        }

        // GATT Client
        bleGattClient = BleGattClient(
            context,
            onIdentityReceived = { address, identity ->
                Timber.d("Identity received from $address: ${identity.size} bytes")
            },
            onDataReceived = { address, data ->
                onDataReceived(address, data, TransportType.BLE)
            }
        )

        // L2CAP Manager (Android 10+)
        bleL2capManager = BleL2capManager(context) { peerId, data ->
            onDataReceived(peerId, data, TransportType.BLE)
        }

        Timber.d("BLE transports initialized")
    } catch (e: Exception) {
        Timber.e(e, "Failed to initialize BLE transports")
    }
}

private fun initializeWifiAware() {
    try {
        wifiAware = WifiAwareTransport(
            context,
            onPeerDiscovered = { peerId, serviceInfo, rssi ->
                Timber.d("WiFi Aware peer discovered: $peerId")
                activeTransports[TransportType.WIFI_AWARE] = true
                peerTransports[peerId] = TransportType.WIFI_AWARE
                onPeerDiscovered(peerId, TransportType.WIFI_AWARE)
                onWifiAwarePeerDiscovered?.invoke(peerId, serviceInfo ?: ByteArray(0), rssi)
            },
            onDataReceived = { peerId, data ->
                onDataReceived(peerId, data, TransportType.WIFI_AWARE)
            },
            onDataPathConfirmed = { peerId, ipAddress, port ->
                onWifiAwareDataPathConfirmed?.invoke(peerId, ipAddress, port)
            }
        )

        if (wifiAware?.isAvailable() == true) {
            Timber.d("WiFi Aware initialized and available")
        } else {
            Timber.d("WiFi Aware not available on this device")
            wifiAware = null
        }
    } catch (e: Exception) {
        Timber.e(e, "Failed to initialize WiFi Aware")
        wifiAware = null
    }
}

private fun initializeWifiDirect() {
    try {
        wifiDirect = WifiDirectTransport(
            context,
            getLocalPeerId = { getLocalPeerId?.invoke() },
            onPeerDiscovered = { peerId, device ->
                Timber.d("WiFi Direct peer discovered: $peerId (address: ${device.deviceAddress})")
                activeTransports[TransportType.WIFI_DIRECT] = true
                peerTransports[peerId] = TransportType.WIFI_DIRECT
                onPeerDiscovered(peerId, TransportType.WIFI_DIRECT)
                onWifiDirectPeerDiscovered?.invoke(peerId, device.deviceName, device.deviceAddress)
            },
            onDataReceived = { peerId, data ->
                onDataReceived(peerId, data, TransportType.WIFI_DIRECT)
            },
            onConnectionInfo = { peerId, groupOwnerIp, isGroupOwner ->
                onWifiDirectConnectionInfo?.invoke(peerId, groupOwnerIp, isGroupOwner)
            }
        )

        Timber.d("WiFi Direct initialized")
    } catch (e: Exception) {
        Timber.e(e, "Failed to initialize WiFi Direct")
        wifiDirect = null
    }
}

fun enableTransport(transport: TransportType) {
    when (transport) {
        TransportType.BLE -> {
            scope.launch { bleScanner?.startScanning() }
            bleAdvertiser?.startAdvertising()
        }
        TransportType.WIFI_AWARE -> {
            if (wifiAware == null) {
                initializeWifiAware()
            }
            wifiAware?.start()
        }
        TransportType.WIFI_DIRECT -> {
            if (wifiDirect == null) {
                initializeWifiDirect()
            }
            wifiDirect?.start()
        }
        TransportType.INTERNET -> {
            // Handled separately by SwarmBridge
        }
        TransportType.TCP_MDNS -> {
            val discovery = getOrCreateMdns()
            discovery.start()
            val probe = getOrCreateSubnetProbe()
            probe.start()
        }
    }
}

fun disableTransport(transport: TransportType) {
    when (transport) {
        TransportType.BLE -> {
            scope.launch { bleScanner?.stopScanning() }
            bleAdvertiser?.stopAdvertising()
        }
        TransportType.WIFI_AWARE -> {
            wifiAware?.stop()
        }
        TransportType.WIFI_DIRECT -> {
            wifiDirect?.stop()
        }
        TransportType.INTERNET -> {
            // Handled separately by SwarmBridge
        }
        TransportType.TCP_MDNS -> {
            mdnsDiscovery?.stop()
            mdnsDiscovery = null
            subnetProbe?.stop()
            subnetProbe = null
        }
    }

    activeTransports.remove(transport)
}

fun getBleQuotaCount(): Int {
    return bleScanner?.getQuotaCount() ?: 0
}

fun applyScanSettings(scanIntervalMs: UInt) {
    Timber.d("Applying BLE scan settings: interval=${scanIntervalMs}ms")
    bleScanner?.applyScanSettings(scanIntervalMs)
}

fun applyAdvertiseSettings(intervalMs: UInt, txPowerDbm: Byte) {
    Timber.d("Applying BLE advertise settings: interval=${intervalMs}ms, txPower=${txPowerDbm}dBm")
    bleAdvertiser?.applyAdvertiseSettings(intervalMs, txPowerDbm)
}

fun handleBleFailure() {
    Timber.w("BLE transport failing, initiating graceful degradation")
    activeTransports.remove(TransportType.BLE)

    // Reduce BLE scan frequency by pausing scanner
    scope.launch { bleScanner?.stopScanning() }
    bleAdvertiser?.stopAdvertising()

    // Prioritize other transports (WiFi Aware and WiFi Direct)
    if (activeTransports[TransportType.WIFI_AWARE] == true) {
        Timber.i("Prioritizing WiFi Aware transport after BLE failure")
    }
    if (activeTransports[TransportType.WIFI_DIRECT] == true) {
        Timber.i("Prioritizing WiFi Direct transport after BLE failure")
    }

    Timber.i("BLE gracefully degraded, using fallback transports")
}

fun attemptBleRecovery() {
    Timber.d("Attempting BLE recovery after degradation cooldown")

    // Check if BLE was previously disabled
    if (activeTransports[TransportType.BLE] != true) {
        // Resume BLE scanning
        scope.launch { bleScanner?.startScanning() }
        bleAdvertiser?.startAdvertising()
        activeTransports[TransportType.BLE] = true

        Timber.i("BLE recovery successful, resuming scanning")
    }
}

fun encodePortTlv(port: Int): ByteArray {
    return byteArrayOf(TLV_TYPE_PORT, 2, ((port shr 8) and 0xff).toByte(), (port and 0xff).toByte())
}

fun decodePortTlv(serviceInfo: ByteArray): Int? {
    var i = 0
    while (i + 1 < serviceInfo.size) {
        val tlvType = serviceInfo[i]
        val tlvLen = serviceInfo[i + 1].toInt() and 0xff
        if (i + 2 + tlvLen > serviceInfo.size) break
        if (tlvType == TLV_TYPE_PORT && tlvLen == 2) {
            return ((serviceInfo[i + 2].toInt() and 0xff) shl 8) or (serviceInfo[i + 3].toInt() and 0xff)
        }
        i += 2 + tlvLen
    }
    return null
}

fun isAvailable(): Boolean {
    return wifiAwareManager?.isAvailable == true
}

fun start() {
    if (isRunning) {
        Timber.w("WiFi Aware already running")
        return
    }

    if (!isAvailable()) {
        Timber.w("WiFi Aware not available on this device")
        return
    }

    try {
        wifiAwareManager?.attach(attachCallback, null)
        Timber.i("Attaching to WiFi Aware...")
    } catch (e: SecurityException) {
        Timber.e(e, "Security exception attaching to WiFi Aware - missing permissions?")
    } catch (e: Exception) {
        Timber.e(e, "Failed to attach to WiFi Aware")
    }
}

fun stop() {
    if (!isRunning) {
        return
    }

    isRunning = false

    scope.cancel()

    // Close all connections
    activeConnections.values.forEach { it.close() }
    activeConnections.clear()

    // Stop publish/subscribe sessions
    publishSession?.close()
    subscribeSession?.close()

    // Unregister network callbacks
    val callbacksToUnregister = synchronized(callbackLock) {
        val callbacks = registeredCallbacks.values.toList()
        registeredCallbacks.clear()
        callbacks
    }
    callbacksToUnregister.forEach { callback ->
        try {
            connectivityManager.unregisterNetworkCallback(callback)
        } catch (e: Exception) {
            Timber.w(e, "Failed to unregister network callback")
        }
    }

    // Detach from WiFi Aware
    awareSession?.close()

    publishSession = null
    subscribeSession = null
    awareSession = null

    Timber.i("WiFi Aware stopped")
}

fun sendData(peerId: String, data: ByteArray): Boolean {
    val connection = activeConnections[peerId] ?: run {
        Timber.w("No WiFi Aware connection to $peerId")
        return false
    }

    return connection.send(data)
}

private fun startPublishing() {
    val config = PublishConfig.Builder()
        .setServiceName(SERVICE_NAME)
        .setPublishType(PublishConfig.PUBLISH_TYPE_UNSOLICITED)
        .build()

    try {
        awareSession?.publish(config, publishDiscoveryCallback, null)
        Timber.d("Publishing WiFi Aware service: $SERVICE_NAME")
    } catch (e: SecurityException) {
        Timber.e(e, "Security exception publishing WiFi Aware service")
    } catch (e: Exception) {
        Timber.e(e, "Failed to publish WiFi Aware service")
    }
}

private fun startSubscribing() {
    val config = SubscribeConfig.Builder()
        .setServiceName(SERVICE_NAME)
        .setSubscribeType(SubscribeConfig.SUBSCRIBE_TYPE_PASSIVE)
        .build()

    try {
        awareSession?.subscribe(config, subscribeDiscoveryCallback, null)
        Timber.d("Subscribing to WiFi Aware service: $SERVICE_NAME")
    } catch (e: SecurityException) {
        Timber.e(e, "Security exception subscribing to WiFi Aware service")
    } catch (e: Exception) {
        Timber.e(e, "Failed to subscribe to WiFi Aware service")
    }
}

private suspend fun createResponderSocket(peerId: String) {
    withContext(blockingSocketDispatcher) {
        var serverSocket: ServerSocket? = null
        try {
            // Network.bindSocket only accepts Socket/DatagramSocket/FileDescriptor.
            // For the responder path we listen on a plain ServerSocket and accept
            // the peer connection established over the Aware data path.
            serverSocket = ServerSocket(AWARE_PORT)

            Timber.d("WiFi Aware responder waiting for connection from $peerId on port $AWARE_PORT")

            val socket = serverSocket.accept()
            serverSocket.close()

            Timber.i("WiFi Aware responder connected to $peerId")
            startLoopbackProxy(peerId, socket)
        } catch (e: Exception) {
            serverSocket?.close()
            Timber.e(e, "Failed to create WiFi Aware responder socket for $peerId")
        }
    }
}

private suspend fun createInitiatorSocket(network: Network, peerId: String, peerIpv6: String) {
    withContext(Dispatchers.IO) {
        try {
            val socket = network.socketFactory.createSocket()
            socket.connect(InetSocketAddress(peerIpv6, AWARE_PORT), CONNECT_TIMEOUT_MS)

            Timber.i("WiFi Aware initiator connected to $peerId at [$peerIpv6]:$AWARE_PORT")
            startLoopbackProxy(peerId, socket)
        } catch (e: Exception) {
            Timber.e(e, "Failed to create WiFi Aware initiator socket for $peerId at [$peerIpv6]")
        }
    }
}

private suspend fun startLoopbackProxy(peerId: String, peerSocket: Socket) {
    val server = try {
        // Bind to the exact address reported to onDataPathConfirmed
        // (LOOPBACK_ADDRESS, "127.0.0.1") rather than
        // InetAddress.getLoopbackAddress(), which resolves to the IPv6
        // loopback (::1) on IPv6-preferring devices - a dial to
        // 127.0.0.1 would then find nobody listening.
        ServerSocket(0, 1, InetAddress.getByName(LOOPBACK_ADDRESS))
    } catch (e: Exception) {
        Timber.e(e, "Failed to bind WiFi Aware loopback proxy for $peerId")
        try { peerSocket.close() } catch (_: Exception) {}
        return
    }

    val connection = AwareConnection(peerId, peerSocket, server)
    activeConnections[peerId] = connection

    val loopbackPort = server.localPort
    Timber.d("WiFi Aware loopback proxy for $peerId listening on 127.0.0.1:$loopbackPort")
    onDataPathConfirmed?.invoke(peerId, LOOPBACK_ADDRESS, loopbackPort)

    scope.launch {
        connection.acceptAndPump()
    }
}

suspend fun acceptAndPump() {
    withContext(blockingSocketDispatcher) {
        val accepted = try {
            loopbackServer.accept()
        } catch (e: Exception) {
            if (!closed) {
                Timber.w(e, "WiFi Aware loopback proxy accept failed for $peerId")
            }
            return@withContext
        } finally {
            try { loopbackServer.close() } catch (_: Exception) {}
        }
        loopbackSocket = accepted

        Timber.d("WiFi Aware loopback proxy for $peerId accepted local dial; bridging streams")

        val peerToLocal = scope.launch(blockingSocketDispatcher) {
            pump(peerSocket.getInputStream(), accepted.getOutputStream(), "peer->local")
        }
        val localToPeer = scope.launch(blockingSocketDispatcher) {
            pump(accepted.getInputStream(), peerSocket.getOutputStream(), "local->peer")
        }
        // Close the whole bridge as soon as either direction's pump
        // finishes (that side's socket hit EOF or errored), not
        // after both: each pump() loops on a blocking read() of its
        // own input stream, so if only one side closed, the other
        // direction's pump would otherwise block in read() forever
        // on a socket nobody will write to again. close() is
        // idempotent, so it's safe to call from whichever
        // completion fires first.
        peerToLocal.invokeOnCompletion { close() }
        localToPeer.invokeOnCompletion { close() }
        peerToLocal.join()
        localToPeer.join()
    }
}

private fun pump(input: InputStream, output: OutputStream, direction: String) {
    try {
        val buffer = ByteArray(8192)
        while (!closed) {
            val bytesRead = input.read(buffer)
            if (bytesRead < 0) break
            if (bytesRead > 0) {
                output.write(buffer, 0, bytesRead)
                output.flush()
            }
        }
    } catch (e: Exception) {
        if (!closed) {
            Timber.d("WiFi Aware proxy stream ended ($direction) for $peerId: ${e.message}")
        }
    }
}

fun send(data: ByteArray): Boolean {
    Timber.e(
        "WiFi Aware sendData() is permanently a no-op for $peerId once its loopback " +
            "proxy is active; delivery happens via libp2p dialing the loopback address " +
            "reported to onDataPathConfirmed, not via this call"
    )
    return false
}

fun close() {
    if (closed) return
    closed = true
    try { peerSocket.close() } catch (e: Exception) { Timber.w(e, "Error closing WiFi Aware peer socket") }
    try { loopbackSocket?.close() } catch (e: Exception) { Timber.w(e, "Error closing WiFi Aware loopback socket") }
    try { loopbackServer.close() } catch (_: Exception) {}
}

fun cleanup() {
    stop()
    scope.cancel()
}

fun start() {
    if (isRunning) {
        Timber.w("WiFi Direct already running")
        return
    }

    if (wifiP2pManager == null) {
        Timber.e("WiFi P2P not available on this device")
        return
    }

    try {
        channel = wifiP2pManager.initialize(context, context.mainLooper, null)

        if (channel == null) {
            Timber.e("Failed to initialize WiFi P2P channel")
            return
        }

        // Register broadcast receiver for P2P events
        val intentFilter = IntentFilter().apply {
            addAction(WifiP2pManager.WIFI_P2P_STATE_CHANGED_ACTION)
            addAction(WifiP2pManager.WIFI_P2P_PEERS_CHANGED_ACTION)
            addAction(WifiP2pManager.WIFI_P2P_CONNECTION_CHANGED_ACTION)
            addAction(WifiP2pManager.WIFI_P2P_THIS_DEVICE_CHANGED_ACTION)
        }

        context.registerReceiver(p2pReceiver, intentFilter)

        isRunning = true

        // Start service discovery
        startServiceDiscovery()

        // Register our service
        registerService()

        Timber.i("WiFi Direct started")
    } catch (e: SecurityException) {
        Timber.e(e, "Security exception starting WiFi Direct - missing permissions?")
    } catch (e: Exception) {
        Timber.e(e, "Failed to start WiFi Direct")
    }
}

fun stop() {
    if (!isRunning) {
        return
    }

    isRunning = false

    try {
        // Stop discovery
        wifiP2pManager?.stopPeerDiscovery(channel, null)

        // Clear service
        wifiP2pManager?.clearLocalServices(channel, null)

        // Disconnect from group
        wifiP2pManager?.removeGroup(channel, null)

        // Close all connections
        activeConnections.values.forEach { it.close() }
        activeConnections.clear()

        // Close server socket
        serverSocket?.close()
        serverSocket = null

        // Unregister receiver
        context.unregisterReceiver(p2pReceiver)

        discoveredPeers.clear()

        Timber.i("WiFi Direct stopped")
    } catch (e: SecurityException) {
        Timber.e(e, "Security exception stopping WiFi Direct")
    } catch (e: Exception) {
        Timber.e(e, "Failed to stop WiFi Direct")
    }
}

fun sendData(peerId: String, data: ByteArray): Boolean {
    val connection = activeConnections[peerId] ?: run {
        Timber.w("No WiFi Direct connection to $peerId")
        return false
    }

    return connection.send(data)
}

private fun startServiceDiscovery() {
    if (channel == null) return

    try {
        val serviceRequest = WifiP2pDnsSdServiceRequest.newInstance()

        wifiP2pManager?.setDnsSdResponseListeners(
            channel,
            { _, _, _ -> },
            { fullDomainName, record, device ->
                Timber.d("WiFi Direct service discovered: $fullDomainName from ${device.deviceName}")

                if (record["service"] == SERVICE_TYPE) {
                    val peerId = record["peer_id"] ?: device.deviceAddress
                    discoveredPeers[device.deviceAddress] = device
                    onPeerDiscovered(peerId, device)

                    // Initiate connection
                    connectToPeer(device)
                }
            }
        )

        wifiP2pManager?.addServiceRequest(channel, serviceRequest, object : WifiP2pManager.ActionListener {
            override fun onSuccess() {
                Timber.d("Service discovery request added")
                startPeerDiscovery()
            }

            override fun onFailure(reason: Int) {
                Timber.e("Failed to add service discovery request: $reason")
            }
        })
    } catch (e: SecurityException) {
        Timber.e(e, "Security exception in service discovery")
    } catch (e: Exception) {
        Timber.e(e, "Failed to start service discovery")
    }
}

private fun startPeerDiscovery() {
    if (channel == null) return

    try {
        wifiP2pManager?.discoverPeers(channel, object : WifiP2pManager.ActionListener {
            override fun onSuccess() {
                Timber.d("Peer discovery started")
            }

            override fun onFailure(reason: Int) {
                Timber.e("Peer discovery failed: $reason")
            }
        })
    } catch (e: SecurityException) {
        Timber.e(e, "Security exception starting peer discovery")
    } catch (e: Exception) {
        Timber.e(e, "Failed to start peer discovery")
    }
}

private fun registerService() {
    if (channel == null) return

    try {
        val localPeerId = getLocalPeerId() ?: ""
        val record = mutableMapOf<String, String>().apply {
            put("service", SERVICE_TYPE)
            put("version", "1.0")
            put("peer_id", localPeerId)
        }

        val serviceInfo = WifiP2pDnsSdServiceInfo.newInstance(
            SERVICE_NAME,
            SERVICE_TYPE,
            record
        )

        wifiP2pManager?.addLocalService(channel, serviceInfo, object : WifiP2pManager.ActionListener {
            override fun onSuccess() {
                Timber.d("WiFi Direct service registered: $SERVICE_NAME")
            }

            override fun onFailure(reason: Int) {
                Timber.e("Failed to register service: $reason")
            }
        })
    } catch (e: SecurityException) {
        Timber.e(e, "Security exception registering service")
    } catch (e: Exception) {
        Timber.e(e, "Failed to register service")
    }
}

private fun connectToPeer(device: WifiP2pDevice) {
    if (channel == null) return

    if (activeConnections.containsKey(device.deviceAddress)) {
        Timber.d("Already connected to ${device.deviceAddress}")
        return
    }

    try {
        val config = WifiP2pConfig().apply {
            deviceAddress = device.deviceAddress
            groupOwnerIntent = computeGroupOwnerIntent()
        }

        wifiP2pManager?.connect(channel, config, object : WifiP2pManager.ActionListener {
            override fun onSuccess() {
                Timber.d("Connection initiated to ${device.deviceAddress}")
            }

            override fun onFailure(reason: Int) {
                Timber.e("Failed to connect to ${device.deviceAddress}: $reason")
            }
        })
    } catch (e: SecurityException) {
        Timber.e(e, "Security exception connecting to peer")
    } catch (e: Exception) {
        Timber.e(e, "Failed to connect to peer")
    }
}

private fun handleConnectionInfo(info: WifiP2pInfo) {
    isGroupOwner = info.isGroupOwner

    Timber.d("Connection info - Group owner: $isGroupOwner, Owner address: ${info.groupOwnerAddress}")

    onConnectionInfo?.invoke(
        "",
        info.groupOwnerAddress?.hostAddress ?: "127.0.0.1",
        info.isGroupOwner
    )

    if (isGroupOwner) {
        // We are group owner - start server
        startServer()
    } else {
        // We are client - connect to group owner
        connectToGroupOwner(info.groupOwnerAddress?.hostAddress ?: "")
    }
}

private fun startServer() {
    scope.launch(acceptDispatcher) {
        try {
            serverSocket = ServerSocket(P2P_PORT)
            Timber.i("WiFi Direct server started on port $P2P_PORT")

            while (isRunning) {
                val socket = serverSocket?.accept()
                if (socket != null) {
                    val peerId = socket.inetAddress.hostAddress ?: "unknown"
                    Timber.d("Incoming WiFi Direct connection from $peerId")

                    val connection = P2pConnection(peerId, socket)
                    activeConnections[peerId] = connection
                    connection.startReading()
                }
            }
        } catch (e: Exception) {
            if (isRunning) {
                Timber.e(e, "WiFi Direct server error")
            }
        }
    }
}

private fun connectToGroupOwner(address: String) {
    scope.launch {
        try {
            val socket = Socket()
            socket.connect(InetSocketAddress(address, P2P_PORT), 5000)

            Timber.i("Connected to WiFi Direct group owner at $address")

            val connection = P2pConnection(address, socket)
            activeConnections[address] = connection
            connection.startReading()
        } catch (e: Exception) {
            Timber.e(e, "Failed to connect to group owner at $address")
        }
    }
}

fun startReading() {
    if (isReading) return

    isReading = true

    scope.launch {
        try {
            val buffer = ByteArray(8192)
            val lengthBuffer = ByteArray(4)

            while (isReading && socket.isConnected) {
                val headerRead = inputStream.read(lengthBuffer)
                if (headerRead < 4) break

                val length = java.nio.ByteBuffer.wrap(lengthBuffer).int
                if (length <= 0 || length > buffer.size) {
                    Timber.e("Invalid message length: $length")
                    break
                }

                val data = ByteArray(length)
                var totalRead = 0
                while (totalRead < length) {
                    val bytesRead = inputStream.read(data, totalRead, length - totalRead)
                    if (bytesRead < 0) break
                    totalRead += bytesRead
                }

                if (totalRead == length) {
                    onDataReceived(peerId, data)
                } else {
                    break
                }
            }
        } catch (e: Exception) {
            if (isReading) {
                Timber.e(e, "WiFi Direct read error from $peerId")
            }
        } finally {
            close()
        }
    }
}

fun send(data: ByteArray): Boolean {
    return try {
        synchronized(outputStream) {
            val lengthBytes = java.nio.ByteBuffer.allocate(4).putInt(data.size).array()
            outputStream.write(lengthBytes)
            outputStream.write(data)
            outputStream.flush()
        }
        true
    } catch (e: Exception) {
        Timber.e(e, "Failed to send WiFi Direct data to $peerId")
        false
    }
}

fun close() {
    isReading = false
    try {
        socket.close()
    } catch (e: Exception) {
        Timber.w(e, "Error closing WiFi Direct socket")
    }
    activeConnections.remove(peerId)
}

fun discoverPeers(): Boolean {
    if (!isRunning) {
        start()
        return true
    }
    startPeerDiscovery()
    return true
}

fun stopDiscovery() {
    if (channel != null) {
        try {
            wifiP2pManager?.stopPeerDiscovery(channel, null)
        } catch (e: SecurityException) {
            Timber.e(e, "Security exception in stopDiscovery")
        }
    }
}

fun connect(deviceAddress: String): Boolean {
    if (channel == null) return false
    try {
        val config = WifiP2pConfig().apply {
            this.deviceAddress = deviceAddress
            groupOwnerIntent = computeGroupOwnerIntent()
        }
        wifiP2pManager?.connect(channel, config, object : WifiP2pManager.ActionListener {
            override fun onSuccess() {
                Timber.d("Connection initiated to $deviceAddress")
            }
            override fun onFailure(reason: Int) {
                Timber.e("Failed to connect to $deviceAddress: $reason")
            }
        })
        return true
    } catch (e: SecurityException) {
        Timber.e(e, "Security exception in connect")
        return false
    }
}

fun createGroup(groupName: String): Boolean {
    if (channel == null) return false
    try {
        wifiP2pManager?.createGroup(channel, object : WifiP2pManager.ActionListener {
            override fun onSuccess() {
                Timber.d("Group created successfully: $groupName")
            }
            override fun onFailure(reason: Int) {
                Timber.e("Failed to create group: $reason")
            }
        })
        return true
    } catch (e: SecurityException) {
        Timber.e(e, "Security exception in createGroup")
        return false
    }
}

fun removeGroup() {
    if (channel != null) {
        try {
            wifiP2pManager?.removeGroup(channel, null)
        } catch (e: Exception) {
            Timber.e(e, "Failed to remove group")
        }
    }
}

fun cleanup() {
    stop()
    scope.cancel()
}

private fun computeGroupOwnerIntent(): Int {
    val batteryStatus = context.registerReceiver(null, IntentFilter(Intent.ACTION_BATTERY_CHANGED))

    val level = batteryStatus?.getIntExtra(BatteryManager.EXTRA_LEVEL, -1) ?: -1
    val scale = batteryStatus?.getIntExtra(BatteryManager.EXTRA_SCALE, -1) ?: -1
    val batteryPct = if (level >= 0 && scale > 0) {
        ((level.toFloat() / scale.toFloat()) * 100).toInt()
    } else {
        100
    }

    val status = batteryStatus?.getIntExtra(BatteryManager.EXTRA_STATUS, -1) ?: -1
    val isCharging = status == BatteryManager.BATTERY_STATUS_CHARGING ||
        status == BatteryManager.BATTERY_STATUS_FULL

    return if (isCharging || batteryPct > 50) {
        GROUP_OWNER_INTENT_PREFERRED
    } else {
        GROUP_OWNER_INTENT_CLIENT
    }
}

fun initialize() {
    channel = manager?.initialize(context, Looper.getMainLooper(), null)
    if (channel == null) {
        Timber.e("Failed to initialize WiFi P2P Manager")
    } else {
        Timber.d("WifiTransportManager initialized")
    }
    if (wifiDirectTransport == null) {
        wifiDirectTransport = WifiDirectTransport(
            context = context,
            getLocalPeerId = { null },
            onPeerDiscovered = { peerId, _ -> onPeerDiscovered(peerId) },
            onDataReceived = { peerId, data ->
                onDataReceived?.invoke(peerId, data)
            }
        )
    }
}

fun startDiscovery() {
    if (isDiscovering) {
        Timber.d("WiFi P2P discovery already active; skipping duplicate start")
        return
    }
    if (!hasDiscoveryPermissions()) {
        Timber.w("WiFi P2P discovery skipped: missing required runtime permissions")
        return
    }
    wifiDirectTransport?.start()
    val c = channel ?: return

    try {
        manager?.discoverPeers(c, object : WifiP2pManager.ActionListener {
            override fun onSuccess() {
                Timber.i("WiFi P2P Discovery started")
                isDiscovering = true
                registerReceiver()
            }

            override fun onFailure(reasonCode: Int) {
                Timber.e("WiFi P2P Discovery failed: $reasonCode")
                isDiscovering = false
            }
        })
    } catch (e: SecurityException) {
        Timber.e(e, "Missing permission while starting WiFi P2P discovery")
        isDiscovering = false
    }
}

fun stopDiscovery() {
    val c = channel
    if (isDiscovering) {
        if (c != null) {
            manager?.stopPeerDiscovery(c, object : WifiP2pManager.ActionListener {
                override fun onSuccess() {
                    isDiscovering = false
                    Timber.i("WiFi P2P Discovery stopped")
                }
                override fun onFailure(reason: Int) {
                    Timber.w("Failed to stop WiFi P2P discovery: $reason")
                }
            })
        }
        isDiscovering = false
        try {
            if (receiverRegistered) {
                context.unregisterReceiver(receiver)
                receiverRegistered = false
            }
        } catch (e: IllegalArgumentException) {
            // Ignore if not registered
        }
    }
    wifiDirectTransport?.stop()
}

private fun registerReceiver() {
    if (receiverRegistered) return
    val intentFilter = IntentFilter().apply {
        addAction(WifiP2pManager.WIFI_P2P_PEERS_CHANGED_ACTION)
        addAction(WifiP2pManager.WIFI_P2P_CONNECTION_CHANGED_ACTION)
    }
    context.registerReceiver(receiver, intentFilter)
    receiverRegistered = true
}

private fun requestPeers() {
    if (!hasDiscoveryPermissions()) {
        Timber.w("WiFi peer request skipped: missing required runtime permissions")
        return
    }
    val c = channel ?: return
    try {
        manager?.requestPeers(c) { peers ->
            peers.deviceList.forEach { device ->
                val peerId = device.deviceAddress // Use MAC as ID for now
                Timber.v("WiFi Peer discovered: $peerId (${device.deviceName})")
                onPeerDiscovered(peerId)
            }
        }
    } catch (e: SecurityException) {
        Timber.e(e, "Missing permission while requesting WiFi peers")
    }
}

private fun hasDiscoveryPermissions(): Boolean {
    val hasLocation = ContextCompat.checkSelfPermission(
        context,
        Manifest.permission.ACCESS_FINE_LOCATION
    ) == PackageManager.PERMISSION_GRANTED
    val hasNearbyWifi = Build.VERSION.SDK_INT < Build.VERSION_CODES.TIRAMISU ||
        ContextCompat.checkSelfPermission(
            context,
            Manifest.permission.NEARBY_WIFI_DEVICES
        ) == PackageManager.PERMISSION_GRANTED
    return hasLocation && hasNearbyWifi
}

fun sendData(peerId: String, data: ByteArray): Boolean {
    val normalizedPeerId = peerId.trim()
    if (normalizedPeerId.isEmpty()) {
        Timber.w("WiFi send skipped: empty peer ID")
        return false
    }
    val direct = wifiDirectTransport
    if (direct == null) {
        Timber.d("WiFi send skipped for $normalizedPeerId: transport not initialized")
        return false
    }
    val sent = direct.sendData(normalizedPeerId, data)
    if (!sent) {
        Timber.d("WiFi send failed for $normalizedPeerId; fallback required")
    }
    return sent
}

fun onStartSuccess(@Suppress("UNUSED_PARAMETER") settingsInEffect: AdvertiseSettings?) {
    Timber.i("BLE Advertising started successfully (mode=${advertiseMode}, txPower=$txPowerLevel)")
    isAdvertising = true
    // ANR FIX: Reset failure counter on success
    advertiseFailureCount = 0
}

fun onStartFailure(errorCode: Int) {
    Timber.e("BLE Advertising failed with error: $errorCode")
    isAdvertising = false

    // ANR FIX: Implement exponential backoff for advertising failures
    advertiseFailureCount++
    val backoffMs = minOf(1000L * (1L shl advertiseFailureCount), 30000L) // Cap at 30s

    when (errorCode) {
        AdvertiseCallback.ADVERTISE_FAILED_TOO_MANY_ADVERTISERS -> {
            Timber.w("BLE advertising failed: Too many advertisers, will retry in ${backoffMs}ms")
        }
        AdvertiseCallback.ADVERTISE_FAILED_ALREADY_STARTED -> {
            Timber.w("BLE advertising failed: Already started, stopping first")
            stopAdvertising()
            return
        }
        AdvertiseCallback.ADVERTISE_FAILED_DATA_TOO_LARGE -> {
            Timber.w("BLE advertising failed: Data too large, falling back to GATT-only mode")
            return // Don't retry for data size errors
        }
        AdvertiseCallback.ADVERTISE_FAILED_FEATURE_UNSUPPORTED -> {
            Timber.w("BLE advertising failed: Feature unsupported on this device")
            return // Don't retry for unsupported features
        }
        else -> {
            Timber.w("BLE advertising failed: Error $errorCode, will retry in ${backoffMs}ms")
        }
    }

    // Schedule retry after backoff delay
    handler.postDelayed({
        if (!isAdvertising && advertiseFailureCount <= 5) { // Max 5 retries
            Timber.d("Retrying BLE advertising (attempt ${advertiseFailureCount + 1})")
            startAdvertising()
        }
    }, backoffMs)
}

fun applyAdvertiseSettings(intervalMs: UInt, txPowerDbm: Byte) {
    // Map interval to advertise mode
    advertiseMode = when {
        intervalMs < 500u -> AdvertiseSettings.ADVERTISE_MODE_LOW_LATENCY
        intervalMs < 1500u -> AdvertiseSettings.ADVERTISE_MODE_BALANCED
        else -> AdvertiseSettings.ADVERTISE_MODE_LOW_POWER
    }

    // Map tx power
    txPowerLevel = when {
        txPowerDbm >= 0 -> AdvertiseSettings.ADVERTISE_TX_POWER_HIGH
        txPowerDbm >= -10 -> AdvertiseSettings.ADVERTISE_TX_POWER_MEDIUM
        txPowerDbm >= -20 -> AdvertiseSettings.ADVERTISE_TX_POWER_LOW
        else -> AdvertiseSettings.ADVERTISE_TX_POWER_ULTRA_LOW
    }

    Timber.d("Advertise settings updated: mode=$advertiseMode, txPower=$txPowerLevel")

    // Restart advertising if active
    if (isAdvertising) {
        stopAdvertising()
        startAdvertising()
    }
}

fun setIdentityData(data: ByteArray) {
    val previous = currentIdentityData
    if (previous?.contentEquals(data) == true) {
        return
    }
    currentIdentityData = data
    Timber.d("Identity data set: ${data.size} bytes")

    // Refresh advertising payload only when service-data visibility can change.
    // Large identity payloads are served via GATT, so restarting advertising
    // for every GATT-only update creates unnecessary churn/disconnect noise.
    val previousWasAdvertisable = (previous?.size ?: 0) <= 24
    val currentIsAdvertisable = data.size <= 24
    val requiresAdvertiseRefresh = previousWasAdvertisable || currentIsAdvertisable

    if (isAdvertising && requiresAdvertiseRefresh) {
        stopAdvertising()
        startAdvertising()
    }
}

fun updateIdentityBeacon(data: ByteArray) {
    setIdentityData(data)
}

fun setRotationInterval(intervalMs: Long) {
    rotationIntervalMs = intervalMs
    Timber.d("Rotation interval set: ${intervalMs}ms")

    if (isAdvertising && intervalMs > 0) {
        startRotation()
    }
}

fun startAdvertising() {
    if (advertiser == null) {
        Timber.w("Bluetooth Advertiser not available")
        return
    }
    if (!hasAdvertisePermission()) {
        Timber.w("BLUETOOTH_ADVERTISE permission missing; cannot start BLE advertising")
        return
    }
    if (isAdvertising) return

    val settings = AdvertiseSettings.Builder()
        .setAdvertiseMode(advertiseMode)
        .setConnectable(true)
        .setTimeout(0)
        .setTxPowerLevel(txPowerLevel)
        .build()

    val dataBuilder = AdvertiseData.Builder()
        .setIncludeDeviceName(false)
        .addServiceUuid(ParcelUuid(BleScanner.SERVICE_UUID))

    // Add identity data if available
    currentIdentityData?.let { data ->
        if (data.size <= 24) {
            dataBuilder.addServiceData(ParcelUuid(BleScanner.SERVICE_UUID), data)
        } else {
            Timber.w("Identity data too large for advertising (${data.size} bytes), using GATT")
        }
    }

    val data = dataBuilder.build()

    try {
        advertiser.startAdvertising(settings, data, advertiseCallback)

        // Start rotation if configured
        if (rotationIntervalMs > 0) {
            startRotation()
        }
    } catch (e: SecurityException) {
        Timber.e(e, "Missing permission while starting BLE advertising")
    } catch (e: Exception) {
        Timber.e(e, "Failed to start BLE advertising")
    }
}

private fun startRotation() {
    // Cancel any existing rotation
    stopRotation()

    rotationRunnable = object : Runnable {
        override fun run() {
            if (isAdvertising && rotationRunnable != null) {
                // Rotate: restart advertising without calling full stop/start cycle
                // This prevents creating new rotation runnables
                try {
                    if (!hasAdvertisePermission()) {
                        Timber.w("BLUETOOTH_ADVERTISE permission missing; skipping beacon rotation")
                        return
                    }
                    advertiser?.stopAdvertising(advertiseCallback)
                    isAdvertising = false

                    // Restart immediately
                    val settings = AdvertiseSettings.Builder()
                        .setAdvertiseMode(advertiseMode)
                        .setConnectable(true)
                        .setTimeout(0)
                        .setTxPowerLevel(txPowerLevel)
                        .build()

                    val dataBuilder = AdvertiseData.Builder()
                        .setIncludeDeviceName(false)
                        .addServiceUuid(ParcelUuid(BleScanner.SERVICE_UUID))

                    currentIdentityData?.let { data ->
                        if (data.size <= 24) {
                            dataBuilder.addServiceData(ParcelUuid(BleScanner.SERVICE_UUID), data)
                        }
                    }

                    advertiser?.startAdvertising(settings, dataBuilder.build(), advertiseCallback)
                    Timber.d("Beacon rotated")
                } catch (e: SecurityException) {
                    Timber.e(e, "Missing permission while rotating beacon")
                } catch (e: Exception) {
                    Timber.e(e, "Failed to rotate beacon")
                }

                // Schedule next rotation only if we're still the active runnable
                if (rotationRunnable == this) {
                    handler.postDelayed(this, rotationIntervalMs)
                }
            }
        }
    }

    val runnable = rotationRunnable ?: return
    handler.postDelayed(runnable, rotationIntervalMs)
    Timber.d("Beacon rotation started: ${rotationIntervalMs}ms interval")
}

private fun stopRotation() {
    rotationRunnable?.let { handler.removeCallbacks(it) }
    rotationRunnable = null
}

fun stopAdvertising() {
    if (advertiser == null || !isAdvertising) return
    if (!hasAdvertisePermission()) {
        Timber.w("BLUETOOTH_ADVERTISE permission missing; cannot stop BLE advertising cleanly")
        isAdvertising = false
        stopRotation()
        return
    }

    try {
        advertiser.stopAdvertising(advertiseCallback)
        isAdvertising = false
        stopRotation()
        Timber.i("BLE Advertising stopped")
    } catch (e: SecurityException) {
        Timber.e(e, "Missing permission while stopping BLE advertising")
    } catch (e: Exception) {
        Timber.e(e, "Failed to stop BLE advertising")
    }
}

fun sendData(data: ByteArray): Boolean {
    if (!hasAdvertisePermission()) {
        Timber.w("BLUETOOTH_ADVERTISE permission missing; cannot send data via BLE advertising")
        return false
    }
    if (data.size > 24) {
        Timber.w("BLE data too large for legacy advertising (${data.size} bytes). Use GATT server.")
        return false
    }

    // Update advertising data with payload
    val packerUuid = ParcelUuid(BleScanner.SERVICE_UUID)
    val advertiseData = AdvertiseData.Builder()
        .setIncludeDeviceName(false)
        .addServiceUuid(packerUuid)
        .addServiceData(packerUuid, data)
        .build()

    if (isAdvertising) {
         stopAdvertising()
    }

    // Restart with new data using configured settings
    try {
        val settings = AdvertiseSettings.Builder()
            .setAdvertiseMode(advertiseMode)
            .setConnectable(true)
            .setTxPowerLevel(txPowerLevel)
            .build()

        advertiser?.startAdvertising(settings, advertiseData, advertiseCallback)
        Timber.d("BLE Advertising updated with data payload")
        return true
    } catch (e: SecurityException) {
        Timber.e(e, "Missing permission while sending data via BLE advertising")
        return false
    } catch (e: Exception) {
         Timber.e(e, "Failed to send data via BLE advertising")
         return false
    }
}

private fun hasAdvertisePermission(): Boolean {
    return Build.VERSION.SDK_INT < Build.VERSION_CODES.S ||
        ContextCompat.checkSelfPermission(
            context,
            Manifest.permission.BLUETOOTH_ADVERTISE
        ) == PackageManager.PERMISSION_GRANTED
}

fun nextDelay(): Long {
    attemptCount++

    // Exponential backoff with jitter
    val delay = minOf(
        (initialDelayMs * Math.pow(multiplier, (attemptCount - 1).toDouble())).toLong(),
        maxDelayMs
    )

    // Add jitter (±20%) to avoid synchronized retry storms
    val jitter = (delay * 0.2).toLong()
    val jitteredDelay = delay - jitter + (Random.nextLong() % (2 * jitter + 1))

    currentDelay = max(0L, jitteredDelay)
    return currentDelay
}

fun reset() {
    currentDelay = initialDelayMs
    attemptCount = 0
}

private fun gattQueue(deviceAddress: String): Channel<() -> Unit> =
    gattOpQueues.getOrPut(deviceAddress) {
        Channel<() -> Unit>(Channel.UNLIMITED).also { ch ->
            val gate = GattOpGate()
            gattOpGates[deviceAddress] = gate
            noResponseWritesOutstanding[deviceAddress] = AtomicInteger(0)
            scope.launch {
                for (op in ch) {
                    // Wait until the previous op's callback has fired before
                    // starting the next one.
                    gate.semaphore.acquire()
                    gate.permitHeld.set(true)
                    try {
                        op()
                    } catch (t: Throwable) {
                        Timber.e(t, "Unhandled GATT op exception for %s", deviceAddress)
                        releaseGattOp(deviceAddress)
                    }
                }
            }
        }
    }

private fun enqueueGattOp(deviceAddress: String, op: () -> Unit): Boolean {
    val result = gattQueue(deviceAddress).trySend(op)
    if (!result.isSuccess) {
        Timber.w("GATT op dropped for %s: channel closed or full", deviceAddress)
    }
    return result.isSuccess
}

private fun releaseGattOp(deviceAddress: String, expectedGatt: BluetoothGatt? = null) {
    if (expectedGatt != null) {
        val activeGatt = activeConnections[deviceAddress]
        if (activeGatt !== expectedGatt) {
            duplicatePermitReleasesIgnored.incrementAndGet()
            Timber.w("Ignoring stale GATT op release for %s (callback from inactive gatt)", deviceAddress)
            return
        }
    }
    val gate = gattOpGates[deviceAddress] ?: return
    val held = gate.permitHeld.compareAndSet(true, false)
    if (!held) {
        duplicatePermitReleasesIgnored.incrementAndGet()
        Timber.w("Ignoring duplicate GATT op release for %s", deviceAddress)
        return
    }
    try {
        gate.semaphore.release()
    } catch (e: IllegalStateException) {
        semaphoreReleaseOverflows.incrementAndGet()
        Timber.e(e, "GATT semaphore release overflow for %s", deviceAddress)
    }
}

fun connect(deviceAddress: String): Boolean {
    connectAttempts.incrementAndGet()
    if (!BluetoothAdapter.checkBluetoothAddress(deviceAddress)) {
        connectFailures.incrementAndGet()
        Timber.w("Skipping BLE connect for invalid device address: %s", deviceAddress)
        return false
    }
    val mismatchBackoffUntil = addressTypeMismatchBackoffUntilMs[deviceAddress] ?: 0L
    if (mismatchBackoffUntil > System.currentTimeMillis()) {
        addressTypeMismatchConnectSkips.incrementAndGet()
        val waitMs = mismatchBackoffUntil - System.currentTimeMillis()
        Timber.w(
            "Skipping BLE connect to %s due to recent address-type mismatch (retry in %d ms)",
            deviceAddress,
            waitMs.coerceAtLeast(0L)
        )
        return false
    }
    // Check connection pool limit
    if (activeConnections.size >= maxConnections) {
        connectFailures.incrementAndGet()
        Timber.w("Connection pool full ($maxConnections), cannot connect to $deviceAddress")
        return false
    }

    // Check if already connected
    if (activeConnections.containsKey(deviceAddress)) {
        Timber.d("Already connected to $deviceAddress")
        return true
    }

    val adapter = bluetoothManager?.adapter
    if (adapter == null) {
        connectFailures.incrementAndGet()
        Timber.e("Bluetooth adapter not available")
        return false
    }

    return try {
        val device = adapter.getRemoteDevice(deviceAddress)
        connectionStates[deviceAddress] = ConnectionState.CONNECTING

        val gatt = device.connectGatt(
            context,
            false, // autoConnect = false for faster connection
            gattCallback,
            // TRANSPORT_LE is deprecated in API 31; use conditional for backwards compatibility
            // 2 is the value of TRANSPORT_LE, which is the correct value for BLE connections
            if (Build.VERSION.SDK_INT >= Build.VERSION_CODES.O) 2 else 0
        ) ?: run {
            Timber.w("connectGatt returned null for %s", deviceAddress)
            connectionStates.remove(deviceAddress)
            connectFailures.incrementAndGet()
            return false
        }

        activeConnections[deviceAddress] = gatt
        connectInitiated.incrementAndGet()
        Timber.d("Connecting to $deviceAddress")

        // Timeout: if still CONNECTING after 15s, close the stale connection.
        // This prevents stale BLE MACs from consuming a connection slot
        // indefinitely (e.g., iOS MAC rotation leaves old MACs unresponsive).
        scope.launch {
            delay(15_000)
            val currentState = connectionStates[deviceAddress]
            if (currentState == ConnectionState.CONNECTING || currentState == ConnectionState.DISCOVERING_SERVICES) {
                Timber.w("BLE connection timeout for $deviceAddress (stuck in ${currentState}), disconnecting")
                disconnect(deviceAddress)
            }
        }

        true
    } catch (e: SecurityException) {
        Timber.e(e, "Security exception connecting to $deviceAddress")
        connectionStates.remove(deviceAddress)
        connectFailures.incrementAndGet()
        false
    } catch (e: Exception) {
        Timber.e(e, "Failed to connect to $deviceAddress")
        connectionStates.remove(deviceAddress)
        connectFailures.incrementAndGet()
        if (e.message?.contains("Address type mismatch", ignoreCase = true) == true) {
            addressTypeMismatchSignals.incrementAndGet()
            addressTypeMismatchBackoffUntilMs[deviceAddress] =
                System.currentTimeMillis() + ADDRESS_TYPE_MISMATCH_BACKOFF_MS
        }
        false
    }
}

fun disconnect(deviceAddress: String) {
    val gatt = activeConnections.remove(deviceAddress) ?: return

    try {
        gatt.disconnect()
        gatt.close()
        connectionStates.remove(deviceAddress)
        negotiatedMtus.remove(deviceAddress)
        gattOpQueues.remove(deviceAddress)?.close()
        gattOpGates.remove(deviceAddress)
        noResponseWritesOutstanding.remove(deviceAddress)
        addressTypeMismatchBackoffUntilMs.remove(deviceAddress)
        serviceDiscoveryRetries.remove(deviceAddress)
        // Clear any in-progress reassembly for this device to prevent stale
        // fragments from a prior connection contaminating a new connection.
        reassemblyBuffers.remove(deviceAddress)
        expectedFragments.remove(deviceAddress)
        disconnectCount.incrementAndGet()
        Timber.d("Disconnected from $deviceAddress")
    } catch (e: SecurityException) {
        Timber.e(e, "Security exception disconnecting from $deviceAddress")
    } catch (e: Exception) {
        Timber.e(e, "Failed to disconnect from $deviceAddress")
    }
}

suspend fun sendData(deviceAddress: String, data: ByteArray): Boolean {
    var targetAddress = deviceAddress
    var gatt = activeConnections[targetAddress]
    if (gatt == null) {
        val activeAddresses = activeConnections.keys.toList()
        if (activeAddresses.size == 1) {
            targetAddress = activeAddresses.first()
            gatt = activeConnections[targetAddress]
            Timber.w(
                "BLE target %s not connected; using sole active connection %s",
                deviceAddress,
                targetAddress
            )
        } else {
            Timber.w("Not connected to %s, requesting reconnect before send", deviceAddress)
            connect(deviceAddress)
            return false
        }
    }
    val activeGatt = gatt ?: run {
        Timber.w("BLE target resolved to %s but connection disappeared before send", targetAddress)
        return false
    }

    val state = connectionStates[targetAddress]
    if (state != ConnectionState.CONNECTED) {
        Timber.w("Cannot send data - not in CONNECTED state for %s: %s", targetAddress, state)
        if (state != ConnectionState.CONNECTING) {
            connect(targetAddress)
        }
        return false
    }

    val service = activeGatt.getService(BleGattServer.SERVICE_UUID)
    val characteristic = service?.getCharacteristic(BleGattServer.MESSAGE_CHAR_UUID)
    if (characteristic == null) {
        Timber.e("Message characteristic not found on $targetAddress")
        return false
    }

    val mtu = negotiatedMtus[targetAddress] ?: 23
    val fragments = fragmentData(data, mtu)

    var allInitiated = true
    for ((index, fragment) in fragments.withIndex()) {
        val initiated = AtomicBoolean(false)
        // Issue 6: CompletableDeferred instead of CountDownLatch — waiting
        // for the GATT op to start suspends the coroutine rather than
        // parking a Dispatchers.IO thread for up to WRITE_INIT_TIMEOUT_MS.
        val initiationSignal = CompletableDeferred<Unit>()
        val enqueued = enqueueGattOp(targetAddress) {
            try {
                characteristic.value = fragment
                // Use write-with-response for deterministic flow control.
                // This is slower than WRITE_TYPE_NO_RESPONSE but avoids reporting
                // false-positive BLE accepts when the stack refuses to start a write.
                characteristic.writeType = BluetoothGattCharacteristic.WRITE_TYPE_DEFAULT
                val didInitiate = activeGatt.writeCharacteristic(characteristic)
                initiated.set(didInitiate)
                if (!didInitiate) {
                    Timber.e(
                        "Failed to initiate characteristic write to %s (fragment=%d/%d)",
                        targetAddress,
                        index + 1,
                        fragments.size
                    )
                    // Callback won't fire when initiation fails.
                    releaseGattOp(targetAddress, activeGatt)
                }
            } catch (e: SecurityException) {
                Timber.e(e, "Security exception sending data to $targetAddress")
                initiated.set(false)
                releaseGattOp(targetAddress, activeGatt)
            } catch (e: Exception) {
                Timber.e(e, "Failed to send data to $targetAddress")
                initiated.set(false)
                releaseGattOp(targetAddress, activeGatt)
            } finally {
                initiationSignal.complete(Unit)
            }
        }
        if (!enqueued) {
            Timber.e(
                "Failed to enqueue BLE write for %s (fragment=%d/%d)",
                targetAddress,
                index + 1,
                fragments.size
            )
            allInitiated = false
            reconnectAfterWriteFailure(targetAddress, "enqueue_failed")
            break
        }
        val started =
            withTimeoutOrNull(WRITE_INIT_TIMEOUT_MS) { initiationSignal.await() } != null
        if (!started || !initiated.get()) {
            allInitiated = false
            reconnectAfterWriteFailure(
                targetAddress,
                if (!started) "start_timeout" else "write_initiation_failed"
            )
            break
        }
    }
    return allInitiated
}

private fun reconnectAfterWriteFailure(deviceAddress: String, reason: String) {
    scope.launch {
        Timber.w(
            "Resetting BLE connection to %s after write failure (%s)",
            deviceAddress,
            reason
        )
        disconnect(deviceAddress)
        delay(300)
        connect(deviceAddress)
    }
}

fun disconnectAll() {
    val addresses = activeConnections.keys.toList()
    addresses.forEach { disconnect(it) }
}

private fun readIdentityBeacon(gatt: BluetoothGatt) {
    enqueueGattOp(gatt.device.address) {
        try {
            val service = gatt.getService(BleGattServer.SERVICE_UUID)
            val characteristic = service?.getCharacteristic(BleGattServer.IDENTITY_CHAR_UUID)
            if (characteristic == null || !gatt.readCharacteristic(characteristic)) {
                // If the op couldn't be initiated, release immediately so the
                // queue doesn't stall.
                releaseGattOp(gatt.device.address, gatt)
            }
            // else: semaphore released in onCharacteristicRead
        } catch (e: SecurityException) {
            Timber.e(e, "Security exception reading identity")
            releaseGattOp(gatt.device.address, gatt)
        } catch (e: Exception) {
            Timber.e(e, "Failed to read identity beacon")
            releaseGattOp(gatt.device.address, gatt)
        }
    }
}

private fun scheduleIdentityRefreshReads(deviceAddress: String) {
    val originalGatt = activeConnections[deviceAddress] ?: return
    // All refresh reads run in a single sequential coroutine to preserve their
    // intended ordering (T+900 ms, then T+2200 ms after connection).  Each
    // read is submitted through enqueueGattOp so it cannot overlap with any
    // other in-flight operation on the same device.
    scope.launch {
        for (delayMs in IDENTITY_REFRESH_DELAYS_MS) {
            delay(delayMs)
            val gatt = activeConnections[deviceAddress] ?: return@launch
            if (gatt !== originalGatt) return@launch
            if (connectionStates[deviceAddress] != ConnectionState.CONNECTED) return@launch
            readIdentityBeacon(gatt)
        }
    }
}

private fun enableMessageNotifications(gatt: BluetoothGatt) {
    enqueueGattOp(gatt.device.address) {
        try {
            val service = gatt.getService(BleGattServer.SERVICE_UUID)
            val characteristic = service?.getCharacteristic(BleGattServer.MESSAGE_CHAR_UUID)
            if (characteristic == null) {
                releaseGattOp(gatt.device.address, gatt)
                return@enqueueGattOp
            }

            // Enable local notification routing (no GATT round-trip needed)
            gatt.setCharacteristicNotification(characteristic, true)

            // Write to CCCD — completion signalled via onDescriptorWrite
            val descriptor = characteristic.getDescriptor(BleGattServer.CLIENT_CONFIG_DESCRIPTOR_UUID)
            if (descriptor != null) {
                descriptor.value = BluetoothGattDescriptor.ENABLE_NOTIFICATION_VALUE
                if (!gatt.writeDescriptor(descriptor)) {
                    Timber.e("CLIENT_CONFIG writeDescriptor returned false for ${gatt.device.address}!")
                    releaseGattOp(gatt.device.address, gatt)
                } else {
                    Timber.w("ENABLE NOTIFICATIONS DESCRIPTOR WRITE INITIATED for ${gatt.device.address}!")
                }
                // else: semaphore released in onDescriptorWrite
            } else {
                Timber.e("CLIENT_CONFIG DESCRIPTOR IS NULL on ${gatt.device.address}! Cannot enable notifications!")
                releaseGattOp(gatt.device.address, gatt)
            }
        } catch (e: SecurityException) {
            Timber.e(e, "Security exception enabling notifications")
            releaseGattOp(gatt.device.address, gatt)
        } catch (e: Exception) {
            Timber.e(e, "Failed to enable notifications")
            releaseGattOp(gatt.device.address, gatt)
        }
    }
}

fun cleanup() {
    scope.cancel()
    disconnectAll()
}

fun setIdentityData(data: ByteArray) {
    identityData = data
    Timber.d("BleGattServer: identity beacon set (${data.size} bytes)")
}

fun start() {
    if (isRunning) {
        Timber.w("GATT server already running")
        return
    }

    bluetoothManager = context.getSystemService(Context.BLUETOOTH_SERVICE) as? BluetoothManager
    if (bluetoothManager == null) {
        Timber.e("BluetoothManager not available")
        return
    }

    try {
        @Suppress("DEPRECATION")
        gattServer = bluetoothManager?.openGattServer(context, gattServerCallback)

        if (gattServer == null) {
            Timber.e("Failed to open GATT server")
            return
        }

        // Add SCMessenger service
        val service = BluetoothGattService(
            SERVICE_UUID,
            BluetoothGattService.SERVICE_TYPE_PRIMARY
        )

        // Identity beacon characteristic (read)
        val identityChar = BluetoothGattCharacteristic(
            IDENTITY_CHAR_UUID,
            BluetoothGattCharacteristic.PROPERTY_READ,
            BluetoothGattCharacteristic.PERMISSION_READ
        )
        service.addCharacteristic(identityChar)

        // Message exchange characteristic (write + write-without-response + notify)
        // PROPERTY_WRITE_NO_RESPONSE allows iOS centrals to use withoutResponse writes
        // for lower-latency bulk fragment delivery (no per-fragment ACK round-trip).
        val messageChar = BluetoothGattCharacteristic(
            MESSAGE_CHAR_UUID,
            BluetoothGattCharacteristic.PROPERTY_WRITE or
                    BluetoothGattCharacteristic.PROPERTY_WRITE_NO_RESPONSE or
                    BluetoothGattCharacteristic.PROPERTY_NOTIFY,
            BluetoothGattCharacteristic.PERMISSION_WRITE
        )
        // Add descriptor for notifications
        val messageDescriptor = BluetoothGattDescriptor(
            CLIENT_CONFIG_DESCRIPTOR_UUID,
            BluetoothGattDescriptor.PERMISSION_READ or BluetoothGattDescriptor.PERMISSION_WRITE
        )
        messageChar.addDescriptor(messageDescriptor)
        service.addCharacteristic(messageChar)

        // Sync handshake characteristic (read + write)
        val syncChar = BluetoothGattCharacteristic(
            SYNC_CHAR_UUID,
            BluetoothGattCharacteristic.PROPERTY_READ or
                    BluetoothGattCharacteristic.PROPERTY_WRITE,
            BluetoothGattCharacteristic.PERMISSION_READ or
                    BluetoothGattCharacteristic.PERMISSION_WRITE
        )
        service.addCharacteristic(syncChar)

        gattServer?.addService(service)
        isRunning = true

        Timber.i("GATT server started with SCMessenger service")
    } catch (e: SecurityException) {
        Timber.e(e, "Security exception starting GATT server - missing permissions?")
    } catch (e: Exception) {
        Timber.e(e, "Failed to start GATT server")
    }
}

fun stop() {
    if (!isRunning) {
        return
    }

    try {
        // Disconnect all clients
        connectedDevices.values.forEach { device ->
            try {
                gattServer?.cancelConnection(device)
            } catch (e: Exception) {
                Timber.w(e, "Error disconnecting device")
            }
        }
        connectedDevices.clear()
        reassemblyBuffers.clear()
        expectedFragments.clear()

        gattServer?.close()
        gattServer = null
        isRunning = false

        Timber.i("GATT server stopped")
    } catch (e: SecurityException) {
        Timber.e(e, "Security exception stopping GATT server")
    } catch (e: Exception) {
        Timber.e(e, "Failed to stop GATT server")
    }
}

suspend fun sendData(deviceAddress: String, data: ByteArray): Boolean {
    val device = connectedDevices[deviceAddress] ?: run {
        Timber.w("Device not connected: $deviceAddress")
        return false
    }

    // Check if device is subscribed to MESSAGE characteristic
    val isSubscribed = subscribedDevices[deviceAddress]?.contains(MESSAGE_CHAR_UUID) == true
    if (!isSubscribed) {
        Timber.w("Device $deviceAddress not subscribed to MESSAGE characteristic")
        return false
    }

    return try {
        val service = gattServer?.getService(SERVICE_UUID)
        val characteristic = service?.getCharacteristic(MESSAGE_CHAR_UUID)

        if (characteristic == null) {
            Timber.e("Message characteristic not found")
            return false
        }

        // Handle MTU fragmentation if needed
        val mtu = deviceMtu[device.address] ?: 23
        if (data.size > mtu - 3) {
            // Fragment and send in chunks
            sendFragmented(device, characteristic, data, mtu)
        } else {
            characteristic.value = data
            notifyCharacteristicChangedSafe(device, characteristic)
        }
    } catch (e: android.os.DeadObjectException) {
        Timber.e("GATT connection dead for $deviceAddress, cleaning up")
        // Force cleanup stale connection
        connectedDevices.remove(deviceAddress)
        subscribedDevices.remove(deviceAddress)
        reassemblyBuffers.remove(deviceAddress)
        expectedFragments.remove(deviceAddress)
        false
    } catch (e: SecurityException) {
        Timber.e(e, "Security exception sending data")
        false
    } catch (e: Exception) {
        Timber.e(e, "Failed to send data to $deviceAddress")
        false
    }
}

fun getConnectedDeviceAddresses(): List<String> {
    return connectedDevices.keys().toList()
}

private fun hasBluetoothConnectPermission(): Boolean {
    return Build.VERSION.SDK_INT < Build.VERSION_CODES.S ||
        ContextCompat.checkSelfPermission(
            context,
            Manifest.permission.BLUETOOTH_CONNECT
        ) == PackageManager.PERMISSION_GRANTED
}

fun isSupported(): Boolean {
    return Build.VERSION.SDK_INT >= Build.VERSION_CODES.Q
}

fun startListening() {
    if (!isSupported()) {
        Timber.w("L2CAP not supported on this device (API < 29)")
        return
    }

    if (isListening) {
        Timber.w("Already listening for L2CAP connections")
        return
    }

    val adapter = bluetoothManager?.adapter
    if (adapter == null) {
        Timber.e("Bluetooth adapter not available")
        return
    }

    scope.launch(acceptDispatcher) {
        try {
            serverSocket = adapter.listenUsingInsecureL2capChannel()
            isListening = true

            val psm = serverSocket?.psm ?: 0
            Timber.i("L2CAP server listening on PSM: $psm")

            // Accept loop
            while (isListening) {
                try {
                    val socket = serverSocket?.accept()
                    if (socket != null) {
                        handleIncomingConnection(socket)
                    }
                } catch (e: Exception) {
                    if (isListening) {
                        Timber.e(e, "Error accepting L2CAP connection")
                    }
                }
            }
        } catch (e: SecurityException) {
            Timber.e(e, "Security exception starting L2CAP server")
            isListening = false
        } catch (e: Exception) {
            Timber.e(e, "Failed to start L2CAP server")
            isListening = false
        }
    }
}

fun stopListening() {
    if (!isListening) {
        return
    }

    isListening = false

    try {
        serverSocket?.close()
        serverSocket = null
        Timber.i("L2CAP server stopped")
    } catch (e: Exception) {
        Timber.e(e, "Error stopping L2CAP server")
    }
}

fun connect(deviceAddress: String, psm: Int): Boolean {
    if (!isSupported()) {
        Timber.w("L2CAP not supported on this device")
        return false
    }

    if (activeConnections.containsKey(deviceAddress)) {
        Timber.d("Already connected to $deviceAddress via L2CAP")
        return true
    }

    val adapter = bluetoothManager?.adapter
    if (adapter == null) {
        Timber.e("Bluetooth adapter not available")
        return false
    }

    scope.launch {
        var socket: BluetoothSocket? = null
        try {
            val device = adapter.getRemoteDevice(deviceAddress)
            socket = device.createInsecureL2capChannel(psm)

            socket.connect()

            val connection = L2capConnection(deviceAddress, socket)
            activeConnections[deviceAddress] = connection

            // Start read loop
            connection.startReading()

            Timber.i("L2CAP connected to $deviceAddress (PSM: $psm)")
        } catch (e: SecurityException) {
            socket?.close()
            Timber.e(e, "Security exception connecting L2CAP to $deviceAddress")
        } catch (e: Exception) {
            socket?.close()
            Timber.e(e, "Failed to connect L2CAP to $deviceAddress")
        }
    }

    return true
}

fun disconnect(deviceAddress: String) {
    val connection = activeConnections.remove(deviceAddress) ?: return
    connection.close()
    Timber.d("L2CAP disconnected from $deviceAddress")
}

fun sendData(deviceAddress: String, data: ByteArray): Boolean {
    val connection = activeConnections[deviceAddress] ?: run {
        Timber.w("No L2CAP connection to $deviceAddress")
        return false
    }

    return connection.send(data)
}

fun shutdown() {
    stopListening()

    val addresses = activeConnections.keys.toList()
    addresses.forEach { disconnect(it) }

    scope.cancel()
}

private fun handleIncomingConnection(socket: BluetoothSocket) {
    val deviceAddress = socket.remoteDevice.address
    Timber.d("Incoming L2CAP connection from $deviceAddress")

    if (activeConnections.containsKey(deviceAddress)) {
        Timber.w("Already have L2CAP connection to $deviceAddress, closing new one")
        socket.close()
        return
    }

    val connection = L2capConnection(deviceAddress, socket)
    activeConnections[deviceAddress] = connection
    connection.startReading()
}

fun startReading() {
    if (isReading) {
        return
    }

    isReading = true

    scope.launch {
        try {
            val buffer = ByteArray(8192) // 8KB buffer

            while (isReading && socket.isConnected) {
                val bytesRead = inputStream.read(buffer)
                if (bytesRead > 0) {
                    val data = buffer.copyOfRange(0, bytesRead)
                    onDataReceived(deviceAddress, data)
                    Timber.d("L2CAP received $bytesRead bytes from $deviceAddress")
                } else if (bytesRead < 0) {
                    // End of stream
                    break
                }
            }
        } catch (e: Exception) {
            if (isReading) {
                Timber.e(e, "L2CAP read error from $deviceAddress")
            }
        } finally {
            close()
        }
    }
}

fun send(data: ByteArray): Boolean {
    return try {
        synchronized(outputStream) {
            outputStream.write(data)
            outputStream.flush()
        }
        Timber.d("L2CAP sent ${data.size} bytes to $deviceAddress")
        true
    } catch (e: Exception) {
        Timber.e(e, "Failed to send L2CAP data to $deviceAddress")
        false
    }
}

fun close() {
    isReading = false

    try {
        socket.close()
    } catch (e: Exception) {
        Timber.w(e, "Error closing L2CAP socket for $deviceAddress")
    }

    activeConnections.remove(deviceAddress, this)
}

fun checkQuota(): Long {
    val now = System.currentTimeMillis()
    pruneOldTimestamps(now)

    return if (scanStartTimestamps.size >= maxScansPerWindow) {
        val oldestInWindow = scanStartTimestamps.first()
        val cooldownMs = windowMs - (now - oldestInWindow) + 500 // 500ms safety margin
        Timber.w("BLE scan quota exhausted ($maxScansPerWindow starts / ${windowMs}ms). Cooldown: ${cooldownMs}ms")
        maxOf(cooldownMs, 1000)
    } else {
        0L
    }
}

fun recordScanStart() {
    val now = System.currentTimeMillis()
    pruneOldTimestamps(now)
    scanStartTimestamps.addLast(now)
}

fun currentCount(): Int {
    pruneOldTimestamps(System.currentTimeMillis())
    return scanStartTimestamps.size
}

private fun pruneOldTimestamps(now: Long) {
    while (scanStartTimestamps.isNotEmpty() && (now - scanStartTimestamps.first()) > windowMs) {
        scanStartTimestamps.removeFirst()
    }
}

fun onScanResult(@Suppress("UNUSED_PARAMETER") callbackType: Int, result: ScanResult?) {
    result?.let { scanResult ->
        val device = scanResult.device
        val peerId = device.address
        if (!matchesMeshAdvertisement(scanResult)) {
            return
        }

        advertisementsSeen.incrementAndGet()
        lastMatchedAdvertisementAtMs.set(System.currentTimeMillis())

        // Check if we've recently seen this peer
        val now = System.currentTimeMillis()
        val lastSeen = recentlySeenPeers[peerId]
        if (lastSeen != null && (now - lastSeen) < peerCacheTimeoutMs) {
            // Skip - we've processed this peer recently
            return
        }

        // Update cache
        recentlySeenPeers[peerId] = now
        peersDiscoveredCount.incrementAndGet()

        // Prune old entries
        pruneOldPeers(now)

        val rssi = scanResult.rssi
        val scanRecord = scanResult.scanRecord

        // Extract Service Data
        val serviceData = scanRecord?.getServiceData(PARCEL_UUID)

        if (serviceData != null) {
            Timber.v("Discovered peer: $peerId (RSSI: $rssi, Data: ${serviceData.size} bytes)")
            // Notify discovery
            onPeerDiscovered(peerId)
            // Notify data received
            onDataReceived(peerId, serviceData)
        } else {
            // Just discovery (legacy or beacon)
            Timber.v("Discovered peer (no data): $peerId (RSSI: $rssi)")
            onPeerDiscovered(peerId)
        }
    }
}

fun onScanFailed(errorCode: Int) {
    val errorDescription = when (errorCode) {
        ScanCallback.SCAN_FAILED_ALREADY_STARTED -> "SCAN_FAILED_ALREADY_STARTED"
        ScanCallback.SCAN_FAILED_APPLICATION_REGISTRATION_FAILED -> "SCAN_FAILED_APPLICATION_REGISTRATION_FAILED"
        ScanCallback.SCAN_FAILED_INTERNAL_ERROR -> "SCAN_FAILED_INTERNAL_ERROR"
        ScanCallback.SCAN_FAILED_FEATURE_UNSUPPORTED -> "SCAN_FAILED_FEATURE_UNSUPPORTED"
        else -> "UNKNOWN_ERROR_$errorCode"
    }

    Timber.e("BLE Scan failed with error code: $errorCode ($errorDescription)")
    scanFailures.incrementAndGet()
    isScanning = false

    // Notify transport manager of BLE failure for graceful degradation
    onScanFailure?.invoke()

    // Schedule retry with exponential backoff for recoverable errors
    when (errorCode) {
        ScanCallback.SCAN_FAILED_ALREADY_STARTED -> {
            Timber.w("BLE scan already started; stopping existing scan before retry")
            scope.launch {
                try {
                    stopScanning()
                    delay(500)
                    startScanning()
                } catch (e: Exception) {
                    Timber.e(e, "Failed to restart BLE scan after already-started error")
                }
            }
        }
        ScanCallback.SCAN_FAILED_APPLICATION_REGISTRATION_FAILED -> {
            Timber.w("BLE scan app registration failed; scheduling retry")
            scope.launch {
                handleScanFailure(Exception("Scan failed: application registration failed (error $errorCode)"))
            }
        }
        ScanCallback.SCAN_FAILED_FEATURE_UNSUPPORTED -> {
            Timber.e("BLE scan feature unsupported on this device; cannot retry")
            // No retry for unsupported feature
        }
        else -> {
            scope.launch {
                handleScanFailure(Exception("Scan failed with error code: $errorCode ($errorDescription)"))
            }
        }
    }
}

suspend fun handleScanFailure(e: Exception): Boolean {
    Timber.e(e, "BLE scan failed")
    // On scan failure, trigger backoff and schedule retry
    isScanning = false
    val retryDelay = backoffStrategy.nextDelay()
    Timber.w("Scheduling BLE scan retry in ${retryDelay}ms due to failure")
    handler.postDelayed({
        scope.launch {
            try {
                startScanning()
            } catch (e: Exception) {
                Timber.e(e, "Failed to restart BLE scan after failure")
            }
        }
    }, retryDelay)
    return false
}

fun applyScanSettings(scanIntervalMs: UInt) {
    // Convert AutoAdjust interval to duty cycle
    val window = minOf(scanIntervalMs.toLong(), 20000L)
    val interval = maxOf(scanIntervalMs.toLong(), window + 5000L)

    setScanDutyCycle(window, interval)
}

fun setScanDutyCycle(windowMs: Long, intervalMs: Long) {
    scanWindowMs = windowMs
    scanIntervalMs = intervalMs
    Timber.d("Scan duty cycle updated: window=${windowMs}ms, interval=${intervalMs}ms")

    // Restart scanning if active
    if (isScanning) {
        scope.launch {
            stopScanning()
            startScanning()
        }
    }
}

fun setBackgroundMode(background: Boolean) {
    if (isBackgroundMode == background) return

    isBackgroundMode = background

    if (background) {
        setScanDutyCycle(BACKGROUND_SCAN_WINDOW_MS, BACKGROUND_SCAN_INTERVAL_MS)
    } else {
        setScanDutyCycle(FOREGROUND_SCAN_WINDOW_MS, FOREGROUND_SCAN_INTERVAL_MS)
    }

    Timber.i("Scan mode changed: background=$background")
}

suspend fun startScanning(): Boolean = scanLock.withLock {
    if (scanner == null) {
        Timber.w("Bluetooth Scanner not available")
        return@withLock false
    }

    // Scan session reuse: if already scanning, don't restart (prevents SCAN_FAILED_ALREADY_STARTED)
    if (isScanning) {
        Timber.d("BLE scan already in progress, reusing existing session")
        return@withLock true
    }

    // Initialize current scan session if needed
    if (currentScanSession == null) {
        currentScanSession = bluetoothAdapter?.bluetoothLeScanner
    }

    val session = currentScanSession
    if (session == null) {
        Timber.w("Bluetooth Scanner not available")
        return@withLock false
    }

    // Check if Bluetooth is enabled
    if (bluetoothAdapter?.isEnabled != true) {
        Timber.w("Bluetooth is not enabled, cannot start scanning")
        return@withLock false
    }

    // Android 12+ Quota Management via BleQuotaManager
    val quotaDelay = quotaManager.checkQuota()
    if (quotaDelay > 0) {
        // Don't set isScanning = false when quota is exhausted
        // Keep the scanning state as false, and schedule retry after quota cooldown
        handler.postDelayed({
            scope.launch {
                try {
                    startScanning()
                } catch (e: Exception) {
                    Timber.e(e, "Failed to restart BLE scan after quota delay")
                }
            }
        }, quotaDelay)
        Timber.w("BLE scan quota exhausted, retrying in ${quotaDelay}ms")
        return@withLock false
    }

    advertisementsSeen.set(0)
    fallbackScanEnabled = false
    scanSessionStartedAtMs.set(System.currentTimeMillis())
    lastMatchedAdvertisementAtMs.set(0L)

    return try {
        // Stop any existing scan first to avoid SCAN_FAILED_ALREADY_STARTED
        // This is safe even if no scan is running (idempotent)
        try {
            session.stopScan(scanCallback)
        } catch (_: Exception) {
            // Ignore errors from stopping non-existent scan
        }

        session.startScan(currentFilters(), buildScanSettings(), scanCallback)
        isScanning = true
        quotaManager.recordScanStart()
        backoffStrategy.reset()
        Timber.i("BLE Scanning started (background=$isBackgroundMode, fallback=$fallbackScanEnabled)")
        scheduleFallbackPromotion()

        // Start duty cycle if intervals are configured
        if (scanWindowMs < scanIntervalMs) {
            startDutyCycle()
        }

        true
    } catch (e: Exception) {
        Timber.e(e, "Failed to start BLE scan")
        // On scan failure, trigger backoff and schedule retry
        isScanning = false
        val retryDelay = backoffStrategy.nextDelay()
        Timber.w("Scheduling BLE scan retry in ${retryDelay}ms due to failure")
        handler.postDelayed({
            scope.launch {
                try {
                    startScanning()
                } catch (e: Exception) {
                    Timber.e(e, "Failed to restart BLE scan after failure")
                }
            }
        }, retryDelay)
        false
    }
}

private fun startDutyCycle() {
    // Cancel any existing duty cycle
    stopDutyCycle()

    dutyCycleRunnable = object : Runnable {
        override fun run() {
            if (isScanning) {
                // Stop scanning for the rest of the interval
                stopScanningInternal()

                // Schedule restart after pause
                handler.postDelayed({
                    if (isScanning) {
                        startScanningInternal()
                    }
                }, scanIntervalMs - scanWindowMs)
            }

            // Schedule next cycle
            if (isScanning) {
                handler.postDelayed(this, scanIntervalMs)
            }
        }
    }

    // Start first cycle after scan window
    val runnable = dutyCycleRunnable ?: return
    handler.postDelayed(runnable, scanWindowMs)
    Timber.d("Duty cycle started: ${scanWindowMs}ms scan / ${scanIntervalMs}ms interval")
}

private fun stopDutyCycle() {
    dutyCycleRunnable?.let { handler.removeCallbacks(it) }
    dutyCycleRunnable = null
}

private fun currentFilters(): List<ScanFilter> {
    return if (fallbackScanEnabled) {
        emptyList()
    } else {
        listOf(
            ScanFilter.Builder()
                .setServiceUuid(ParcelUuid(SERVICE_UUID))
                .build()
        )
    }
}

private fun buildScanSettings(): ScanSettings {
    val scanMode = if (isBackgroundMode) {
        ScanSettings.SCAN_MODE_LOW_POWER
    } else {
        ScanSettings.SCAN_MODE_LOW_LATENCY
    }

    return ScanSettings.Builder()
        .setScanMode(scanMode)
        .setMatchMode(ScanSettings.MATCH_MODE_AGGRESSIVE)
        .setCallbackType(ScanSettings.CALLBACK_TYPE_ALL_MATCHES)
        .setNumOfMatches(ScanSettings.MATCH_NUM_ONE_ADVERTISEMENT)
        .build()
}

private fun scheduleFallbackPromotion() {
    fallbackPromotionRunnable?.let { handler.removeCallbacks(it) }
    fallbackPromotionRunnable = Runnable {
        if (!isScanning || fallbackScanEnabled) {
            return@Runnable
        }
        if (advertisementsSeen.get() > 0 || lastMatchedAdvertisementAtMs.get() > 0L) {
            return@Runnable
        }
        val elapsedMs = System.currentTimeMillis() - scanSessionStartedAtMs.get()
        if (elapsedMs < FALLBACK_SCAN_PROMOTION_DELAY_MS) {
            return@Runnable
        }
        fallbackScanEnabled = true
        Timber.w(
            "BLE scan fallback enabled after %d ms without mesh advertisements; switching to unfiltered scan",
            elapsedMs
        )
        restartActiveScan()
    }
    handler.postDelayed(fallbackPromotionRunnable!!, FALLBACK_SCAN_PROMOTION_DELAY_MS)
}

private fun restartActiveScan() {
    val s = scanner
    if (s == null || !isScanning) return

    try {
        s.stopScan(scanCallback)
    } catch (_: Exception) {
    }

    try {
        s.startScan(currentFilters(), buildScanSettings(), scanCallback)
        Timber.i("BLE scan restarted (background=$isBackgroundMode, fallback=$fallbackScanEnabled)")
    } catch (e: Exception) {
        Timber.e(e, "Failed to restart BLE scan")
    }
}

private fun matchesMeshAdvertisement(result: ScanResult): Boolean {
    val record = result.scanRecord
    val serviceUuidMatch = record?.serviceUuids?.any { it.uuid == SERVICE_UUID } == true
    val serviceDataMatch = record?.getServiceData(PARCEL_UUID) != null
    val advertisedName = record?.deviceName?.trim()
    val deviceName = try { result.device.name?.trim() } catch (_: SecurityException) { null }
    val nameMatch = advertisedName == ADVERTISED_NAME || deviceName == ADVERTISED_NAME

    return serviceUuidMatch || serviceDataMatch || nameMatch
}

private fun startScanningInternal() {
    val s = scanner
    if (s == null || isScanning) return

    try {
        s.startScan(currentFilters(), buildScanSettings(), scanCallback)
        isScanning = true
        Timber.v("BLE scan window started")
    } catch (e: Exception) {
        Timber.e(e, "Failed to restart BLE scan")
        // Set isScanning to false so retry logic can trigger
        isScanning = false
    }
}

private fun stopScanningInternal() {
    val s = scanner
    if (s == null) return

    try {
        s.stopScan(scanCallback)
        Timber.v("BLE scan window ended")
    } catch (e: Exception) {
        Timber.e(e, "Failed to stop BLE scan window")
    }
}

fun forceRestartScanning() {
    Timber.i("Force restarting BLE scanning with backoff")
    isScanning = false
    val retryDelay = backoffStrategy.nextDelay()
    Timber.w("Scheduling BLE scan force restart in ${retryDelay}ms")
    handler.postDelayed({
        scope.launch {
            try {
                startScanning()
            } catch (e: Exception) {
                Timber.e(e, "Failed to restart BLE scan after force restart")
            }
        }
    }, retryDelay)
}

suspend fun stopScanning() = scanLock.withLock {
    stopScanningLocked()
}

private fun stopScanningLocked() {
    if (currentScanSession == null || !isScanning) {
        // P1_ANDROID_022: even if we are not actively scanning, ensure any stale
        // peer cache is purged so re-discovery can occur on the next session.
        clearPeerCache()
        return
    }

    stopDutyCycle()
    fallbackPromotionRunnable?.let { handler.removeCallbacks(it) }
    fallbackPromotionRunnable = null

    try {
        currentScanSession?.stopScan(scanCallback)
        isScanning = false
        Timber.i("BLE Scanning stopped")
    } catch (e: Exception) {
        Timber.e(e, "Failed to stop BLE scan")
    }
    // P1_ANDROID_022: drop stale cache entries on every stop so subsequent
    // discovery sessions don't suppress already-seen peers (gratuitous
    // persistence between runs). See P1_ANDROID_022_BLE_Stale_Cache_Cleanup.
    clearPeerCache()
}

suspend fun onTransportPause() = scanLock.withLock {
    Timber.i("BLE transport paused — stopping scan and clearing peer cache")
    stopScanningLocked()
    clearPeerCache()
}

fun clearPeerCache() {
    recentlySeenPeers.clear()
    Timber.d("Peer cache cleared")
}

fun getDiscoveryStats(): BleDiscoveryStats {
    return BleDiscoveryStats(
        advertisementsSeen = advertisementsSeen.get(),
        peersDiscovered = peersDiscoveredCount.get(),
        scanFailures = scanFailures.get(),
        peerCacheSize = recentlySeenPeers.size
    )
}

fun getQuotaCount(): Int {
    return quotaManager.currentCount()
}

private fun pruneOldPeers(currentTimeMs: Long) {
    val iterator = recentlySeenPeers.entries.iterator()
    while (iterator.hasNext()) {
        val entry = iterator.next()
        if ((currentTimeMs - entry.value) > peerCacheTimeoutMs) {
            iterator.remove()
        }
    }
}

private fun schedulePermissionReset() {
    handler.postDelayed({
        permissionRequestInProgress.set(false)
        Timber.d("Permission request state reset")
    }, permissionRequestDebounceMs)
}

private fun startAnrMonitoring() {
    try {
        anrWatchdog = AnrWatchdog(this)
        anrWatchdog.start()
        Timber.i("ANR watchdog started for UI thread monitoring")
    } catch (e: Exception) {
        Timber.w(e, "Failed to start ANR watchdog")
    }
}

private fun initializeUiComponents() {
    try {
        // Initialize repository (heavy storage/FFI operations)
        meshRepository.initializeRepository()

        // Pre-warm compose state caches
        Timber.d("UI components initialization completed")
    } catch (e: Exception) {
        Timber.e(e, "Failed to initialize UI components")
    }
}

private fun checkPermissions() {
    // Prevent concurrent permission requests
    if (!permissionRequestInProgress.compareAndSet(false, true)) {
        Timber.d("Permission request already in progress, skipping")
        return
    }

    val permissions = mutableListOf(
        Manifest.permission.ACCESS_FINE_LOCATION,
        Manifest.permission.ACCESS_COARSE_LOCATION
    )

    if (Build.VERSION.SDK_INT >= Build.VERSION_CODES.S) {
        permissions.add(Manifest.permission.BLUETOOTH_SCAN)
        permissions.add(Manifest.permission.BLUETOOTH_ADVERTISE)
        permissions.add(Manifest.permission.BLUETOOTH_CONNECT)
    }

    if (Build.VERSION.SDK_INT >= Build.VERSION_CODES.TIRAMISU) {
        permissions.add(Manifest.permission.POST_NOTIFICATIONS)
        permissions.add(Manifest.permission.NEARBY_WIFI_DEVICES)
    }

    val toRequest = permissions.filter {
        ContextCompat.checkSelfPermission(this, it) != PackageManager.PERMISSION_GRANTED
    }

    if (toRequest.isEmpty()) {
        permissionRequestInProgress.set(false)
        Timber.d("All permissions already granted")
        return
    }

    // Determine which permissions need a rationale dialog
    val rationalePermissions = toRequest.filter {
        shouldShowRequestPermissionRationale(it)
    }

    if (rationalePermissions.isNotEmpty()) {
        showPermissionRationale(rationalePermissions, toRequest)
    } else {
        Timber.i("Requesting permissions: $toRequest")
        requestPermissionLauncher.launch(toRequest.toTypedArray())
    }
}

private fun requestNotificationPermissionIfNeeded() {
    if (Build.VERSION.SDK_INT < Build.VERSION_CODES.TIRAMISU) return

    val alreadyGranted = ContextCompat.checkSelfPermission(
        this,
        Manifest.permission.POST_NOTIFICATIONS
    ) == PackageManager.PERMISSION_GRANTED

    if (alreadyGranted) {
        Timber.d("POST_NOTIFICATIONS already granted; skipping rationale")
        return
    }

    if (notificationRationaleShown) {
        // The system dialog will be re-launched from the rationale
        // dialog's positive button instead.
        return
    }
    notificationRationaleShown = true

    val needsRationale = shouldShowRequestPermissionRationale(
        Manifest.permission.POST_NOTIFICATIONS
    )

    if (needsRationale) {
        // User previously denied — explain why we need it again.
        AlertDialog.Builder(this)
            .setTitle(R.string.notification_permission_rationale_title)
            .setMessage(R.string.notification_permission_rationale_message)
            .setPositiveButton(R.string.notification_permission_request_button) { _, _ ->
                Timber.i("Requesting POST_NOTIFICATIONS after rationale")
                notificationPermissionLauncher.launch(Manifest.permission.POST_NOTIFICATIONS)
            }
            .setNegativeButton(R.string.notification_permission_skip_button) { _, _ ->
                Timber.w("User declined POST_NOTIFICATIONS rationale")
            }
            .setCancelable(true)
            .show()
    } else {
        // First time — fire the system dialog directly.
        Timber.i("Requesting POST_NOTIFICATIONS (first time)")
        notificationPermissionLauncher.launch(Manifest.permission.POST_NOTIFICATIONS)
    }
}

fun MeshApp(mainViewModel: MainViewModel = hiltViewModel()) {
    val hasIdentity by mainViewModel.hasIdentity.collectAsState()
    val showOnboarding by mainViewModel.showOnboarding.collectAsState()
    val isStorageLow by mainViewModel.isStorageLow.collectAsState()
    val availableStorageMB by mainViewModel.availableStorageMB.collectAsState()
    val navController = rememberNavController()
    val pendingDeepLink by mainViewModel.pendingDeepLink.collectAsState()
    val pendingRequestsInbox by mainViewModel.pendingRequestsInbox.collectAsState()

    LaunchedEffect(Unit) {
        mainViewModel.refreshIdentityState()
    }

    // Navigate to AddContact when a deep link arrives and identity is ready
    LaunchedEffect(pendingDeepLink, hasIdentity) {
        if (pendingDeepLink != null && hasIdentity) {
            navController.navigate(Screen.AddContact.route) {
                launchSingleTop = true
            }
        }
    }

    // Issue #6: Debounce hasIdentity changes to prevent transient false from causing
    // navigation jumps. We track the "stable" identity state to avoid flicker.
    var hasStableIdentity by remember { mutableStateOf(hasIdentity) }

    LaunchedEffect(hasIdentity) {
        // Debounce: only update stable identity after a short delay
        // This prevents transient false values from triggering navigation jumps
        kotlinx.coroutines.delay(300L)
        hasStableIdentity = hasIdentity
    }

    // Navigate to add contact when deep link arrives
    LaunchedEffect(pendingDeepLink, hasStableIdentity) {
        if (pendingDeepLink != null && hasStableIdentity) {
            navController.navigate(Screen.AddContact.route) {
                launchSingleTop = true
            }
        }
    }

    // Navigate to requests inbox when ACTION_OPEN_REQUESTS is triggered
    LaunchedEffect(pendingRequestsInbox, hasStableIdentity) {
        if (pendingRequestsInbox != null && hasStableIdentity) {
            navController.navigate(Screen.RequestsInbox.route) {
                launchSingleTop = true
                popUpTo(navController.graph.startDestinationId) {
                    saveState = true
                }
            }
        }
    }

    // Navigation guard: only trigger when stable identity state changes
    LaunchedEffect(hasStableIdentity) {
        val currentRoute = navController.currentBackStackEntry?.destination?.route
        val allowedRoutes = roleBasedBottomNavItems(hasStableIdentity).map { it.route }.toSet()
        if (currentRoute != null && currentRoute !in allowedRoutes && !currentRoute.startsWith("chat/")) {
            navController.navigate(startDestinationForRole(hasStableIdentity)) {
                launchSingleTop = true
            }
        }
    }

    Column(modifier = Modifier.fillMaxSize()) {
        if (isStorageLow) {
            com.scmessenger.android.ui.components.StorageWarningBanner(availableMB = availableStorageMB)
        }

        if (showOnboarding) {
            OnboardingScreen(
                onOnboardingComplete = { mainViewModel.refreshIdentityState() },
                viewModel = mainViewModel,
                modifier = Modifier.weight(1f)
            )
        } else {
            // Track current route so the outer Scaffold can host a
            // per-screen FAB without nesting a Scaffold inside the
            // Contacts screen. Nested Scaffolds previously hid the "+" FAB.
            val navBackStackEntry by navController.currentBackStackEntryAsState()
            val currentRoute = navBackStackEntry?.destination?.route
            val isContactsScreen = currentRoute == Screen.Contacts.route

            Scaffold(
                modifier = Modifier.weight(1f),
                bottomBar = { MeshBottomBar(navController = navController, hasIdentity = hasIdentity) },
                floatingActionButton = {
                    if (isContactsScreen) {
                        FloatingActionButton(
                            onClick = { navController.navigate(Screen.AddContact.route) }
                        ) {
                            Icon(
                                imageVector = Icons.Default.Add,
                                contentDescription = stringResource(R.string.app_content_desc_add_contact)
                            )
                        }
                    }
                }
            ) { paddingValues ->
                MeshNavHost(
                    navController = navController,
                    hasIdentity = hasIdentity,
                    onIdentityChanged = { mainViewModel.refreshIdentityState() },
                    bottomPadding = paddingValues
                )
            }
        }
    }
}

fun MeshBottomBar(navController: NavHostController, hasIdentity: Boolean) {
    val navBackStackEntry by navController.currentBackStackEntryAsState()
    val currentRoute = navBackStackEntry?.destination?.route

    // Hide bottom bar on Chat screen
    if (currentRoute?.startsWith("chat/") == true) return

    NavigationBar {
        roleBasedBottomNavItems(hasIdentity).forEach { screen ->
            NavigationBarItem(
                icon = { Icon(screen.icon, contentDescription = screen.label) },
                label = { Text(screen.label) },
                selected = currentRoute == screen.route,
                onClick = {
                    navController.navigate(screen.route) {
                        popUpTo(navController.graph.startDestinationId) {
                            saveState = true
                        }
                        launchSingleTop = true
                        restoreState = true
                    }
                }
            )
        }
    }
}

private fun formatTimestamp(timestamp: ULong): String {
    val millis = timestamp.toEpochMillis()
    val date = Date(millis)
    val now = Date()

    val sdf = if (isSameDay(date, now)) {
        SimpleDateFormat("HH:mm", Locale.getDefault())
    } else {
        SimpleDateFormat("MMM d, HH:mm", Locale.getDefault())
    }

    return sdf.format(date)
}

private fun isSameDay(date1: Date, date2: Date): Boolean {
    val cal1 = Calendar.getInstance().apply { time = date1 }
    val cal2 = Calendar.getInstance().apply { time = date2 }

    return cal1.get(Calendar.YEAR) == cal2.get(Calendar.YEAR) &&
           cal1.get(Calendar.DAY_OF_YEAR) == cal2.get(Calendar.DAY_OF_YEAR)
}

