private fun generateSaltFromTouchPoints(points: List<TouchPoint>): ByteArray {
    val byteBuffer = ByteBuffer.allocate(points.size * 16)
    points.forEach { point ->
        byteBuffer.putFloat(point.x)
        byteBuffer.putFloat(point.y)
        byteBuffer.putLong(point.timestamp)
    }
    val md = MessageDigest.getInstance("SHA-256")
    val hash = md.digest(byteBuffer.array())
    return hash.copyOf(16)
}

fun mapErrorToMessage(error: String): String {
    return when {
        error.contains("IronCoreError", ignoreCase = true) -> "Failed to connect to mesh network"
        error.contains("permission", ignoreCase = true) -> "Permission required to continue"
        error.contains("bluetooth", ignoreCase = true) -> "Bluetooth error - check settings"
        error.contains("wifi", ignoreCase = true) -> "WiFi error - check connection"
        error.contains("timeout", ignoreCase = true) -> "Connection timeout - try again"
        error.contains("not found", ignoreCase = true) -> "Peer not found"
        error.contains("encrypt", ignoreCase = true) -> "Failed to encrypt message"
        error.contains("decrypt", ignoreCase = true) -> "Failed to decrypt message"
        else -> error
    }
}

private fun generateColors(data: ByteArray): List<Color> {
    if (data.isEmpty()) {
        return listOf(Color.Gray, Color.LightGray, Color.DarkGray)
    }

    val hue = (data[0].toInt() and 0xFF) / 255f * 360f
    val saturation = if (data.size > 1) {
        (data[1].toInt() and 0xFF) / 255f * 0.5f + 0.5f
    } else {
        0.7f
    }

    val primary = Color.hsv(hue, saturation, 0.9f)
    val secondary = Color.hsv((hue + 120) % 360, saturation, 0.8f)
    val tertiary = Color.hsv((hue + 240) % 360, saturation, 0.7f)
    val accent = Color.hsv((hue + 60) % 360, saturation * 0.7f, 1.0f)

    return listOf(primary, secondary, tertiary, accent)
}

private fun generatePattern(data: ByteArray): List<Int> {
    if (data.isEmpty()) {
        return List(6) { 50 }
    }

    return List(6) { index ->
        val byteIndex = index % data.size
        data[byteIndex].toInt() and 0xFF
    }
}

private fun Color.toArgb(): Int {
    return android.graphics.Color.argb(
        (alpha * 255).toInt(),
        (red * 255).toInt(),
        (green * 255).toInt(),
        (blue * 255).toInt()
    )
}

fun generateQrCodeBitmap(data: String, size: Int): Bitmap {
    val writer = QRCodeWriter()
    val bitMatrix = writer.encode(data, BarcodeFormat.QR_CODE, size, size)

    val width = bitMatrix.width
    val height = bitMatrix.height

    // Fill an IntArray in Kotlin and hand it to the bitmap in one call,
    // instead of up to 262,144 (512x512) individual JNI setPixel calls on
    // the main thread.
    val pixels = IntArray(width * height)
    for (y in 0 until height) {
        val rowOffset = y * width
        for (x in 0 until width) {
            pixels[rowOffset + x] =
                if (bitMatrix[x, y]) android.graphics.Color.BLACK else android.graphics.Color.WHITE
        }
    }

    return Bitmap.createBitmap(pixels, width, height, Bitmap.Config.RGB_565)
}

