private fun handleHttpClient(socket: Socket, apkFile: File) {
    try {
        socket.use { s ->
            val output: OutputStream = s.getOutputStream()
            val header = buildString {
                append("HTTP/1.1 200 OK\r\n")
                append("Content-Type: application/vnd.android.package-archive\r\n")
                append("Content-Length: ${apkFile.length()}\r\n")
                append("Content-Disposition: attachment; filename=\"scmessenger-v0.4.0.apk\"\r\n")
                append("Connection: close\r\n\r\n")
            }
            output.write(header.toByteArray(Charsets.UTF_8))
            output.flush()

            FileInputStream(apkFile).use { input ->
                val buffer = ByteArray(8192)
                var bytesRead: Int
                while (input.read(buffer).also { bytesRead = it } != -1) {
                    output.write(buffer, 0, bytesRead)
                }
            }
            output.flush()
            Timber.i("Successfully served APK download to ${s.inetAddress.hostAddress}")
        }
    } catch (e: Exception) {
        Timber.w(e, "Error serving APK client request")
    }
}

fun nextDelay(): Long {
    synchronized(lock) {
        val attempt = attemptCount.getAndIncrement()

        // Calculate exponential backoff
        val baseDelay = (initialDelayMs * Math.pow(multiplier, attempt.toDouble())).toLong()

        // Apply jitter to prevent synchronized retry storms
        // Jitter: ±jitterFactor * delay
        val jitter = (baseDelay * jitterFactor).toLong()
        val jitteredDelay = min(baseDelay - jitter + Random.nextLong(-jitter, jitter + 1), maxDelayMs)

        Timber.d("Backoff: attempt=${attempt + 1}, delay=${jitteredDelay}ms")

        return maxOf(0, jitteredDelay)
    }
}

fun getCurrentDelay(): Long {
    synchronized(lock) {
        val attempt = attemptCount.get()
        val baseDelay = (initialDelayMs * Math.pow(multiplier, attempt.toDouble())).toLong()
        return min(baseDelay, maxDelayMs)
    }
}

fun reset() {
    synchronized(lock) {
        attemptCount.set(0)
        Timber.d("Backoff strategy reset")
    }
}

fun getAttemptCount(): Int = attemptCount.get()

/**
 * Check if we've exceeded the max delay.
 */
fun isAtMaxDelay(): Boolean {
    synchronized(lock) {
        return getCurrentDelay() >= maxDelayMs
    }
}

fun BackoffStrategy.getBackoffLogString(): String {
    val current = getCurrentDelay()
    return "backoff(current=${current}ms, max=${maxDelayMs}ms, attempts=${getAttemptCount()})"
}

fun validateBackupPassphrase(passphrase: String, confirmation: String): BackupPassphraseValidation {
    return when {
        // codePointCount, not length: String.length counts UTF-16 code
        // units, so a passphrase of surrogate-pair characters (e.g. most
        // emoji) reports roughly double its actual character count and
        // could pass this check with far fewer real characters than intended.
        passphrase.codePointCount(0, passphrase.length) < MIN_BACKUP_PASSPHRASE_LENGTH ->
            BackupPassphraseValidation.TooShort
        passphrase != confirmation -> BackupPassphraseValidation.Mismatch
        else -> BackupPassphraseValidation.Valid
    }
}

suspend fun allowRequest(relayAddress: String): Boolean = mutex.withLock {
    val entry = entries[relayAddress] ?: return true

    when (entry.state) {
        CircuitState.CLOSED -> true
        CircuitState.OPEN -> {
            val elapsed = System.currentTimeMillis() - entry.openedAtMs
            if (elapsed >= config.openTimeoutMs) {
                // Transition to half-open
                Timber.d("Circuit breaker HALF-OPEN for relay %s", relayAddress)
                entry.state = CircuitState.HALF_OPEN
                entry.halfOpenStartedAtMs = System.currentTimeMillis()
                entry.halfOpenProbes++
                entry.successCount = 0
                true
            } else {
                Timber.d("Circuit breaker OPEN for relay %s, skipping", relayAddress)
                false
            }
        }
        CircuitState.HALF_OPEN -> {
            if (entry.halfOpenProbes < config.maxHalfOpenProbes) {
                true
            } else {
                Timber.d("Circuit breaker HALF-OPEN max probes reached for relay %s", relayAddress)
                false
            }
        }
    }
}

suspend fun recordSuccess(relayAddress: String) = mutex.withLock {
    val entry = entries.getOrPut(relayAddress) { CircuitEntry() }
    entry.lastSuccessAtMs = System.currentTimeMillis()
    entry.lastFailureReason = null

    when (entry.state) {
        CircuitState.CLOSED -> {
            entry.failureCount = 0
        }
        CircuitState.HALF_OPEN -> {
            entry.successCount++
            if (entry.successCount >= config.successThreshold) {
                Timber.i("Circuit breaker CLOSING for relay %s after %d successful probes",
                    relayAddress, entry.successCount)
                entry.state = CircuitState.CLOSED
                entry.failureCount = 0
                entry.successCount = 0
                entry.halfOpenProbes = 0
                entry.openedAtMs = 0L
                entry.halfOpenStartedAtMs = 0L
            }
        }
        CircuitState.OPEN -> {
            Timber.d("Unexpected success on OPEN circuit for relay %s", relayAddress)
        }
    }
}

suspend fun recordFailure(relayAddress: String, reason: String) = mutex.withLock {
    val entry = entries.getOrPut(relayAddress) { CircuitEntry() }
    entry.failureCount++
    entry.lastFailureReason = reason

    when (entry.state) {
        CircuitState.CLOSED -> {
            if (entry.failureCount >= config.failureThreshold) {
                Timber.w("Circuit breaker OPENING for relay %s after %d failures: %s",
                    relayAddress, entry.failureCount, reason)
                entry.state = CircuitState.OPEN
                entry.openedAtMs = System.currentTimeMillis()
                entry.successCount = 0
            }
        }
        CircuitState.HALF_OPEN -> {
            Timber.w("Circuit breaker RE-OPENING for relay %s after failed probe: %s",
                relayAddress, reason)
            entry.state = CircuitState.OPEN
            entry.openedAtMs = System.currentTimeMillis()
            entry.successCount = 0
            entry.halfOpenProbes = 0
            entry.halfOpenStartedAtMs = 0L
        }
        CircuitState.OPEN -> {
            entry.openedAtMs = System.currentTimeMillis()
        }
    }
}

