fun normalize(id: String): String {
    val trimmed = id.trim()
    // 64 hex chars are case-insensitive public keys - normalize to lower
    if (trimmed.length == 64 && trimmed.matches(IDENTITY_ID_REGEX)) {
        return trimmed.lowercase()
    }
    // Base58 libp2p IDs (starting with 12D3Koo or Qm) are case-sensitive - preserve case
    return trimmed
}

fun isLibp2pPeerId(id: String): Boolean {
    // Base58-encoded libp2p peer IDs: 12D3KooW... (~52 chars) or Qm... (~46 chars)
    // Validate prefix + reasonable length + base58 charset (no 0, O, I, l)
    val base58Chars = id.all { c -> c.isLetterOrDigit() && c !in "0OIl" }
    return base58Chars && (
        (id.startsWith("12D3Koo") && id.length in 46..56) ||
        (id.startsWith("Qm") && id.length in 44..50)
    )
}

fun extractPublicKeyFromPeerId(peerId: String): String? {
    return try {
        if (!isLibp2pPeerId(peerId)) {
            Timber.w("Peer ID does not appear to be a libp2p peer ID: $peerId")
            return null
        }

        // Decode from base58
        val decoded = base58Decode(peerId)
        if (decoded == null || decoded.size < 35) {
            Timber.w("Decoded peer ID too short: ${decoded?.size ?: 0}")
            return null
        }

        // Verify the format: first byte should be 0x12 (Ed25519)
        if (decoded[0] != 0x12.toByte()) {
            Timber.w("Invalid multihash prefix: 0x${decoded[0].toInt().toHex()}")
            return null
        }

        // Extract the 32-byte public key (bytes 2-33)
        val publicKeyBytes = decoded.copyOfRange(2, 34)

        // Verify checksum (bytes 34+ should match first 2 bytes of SHA256(publicKey))
        if (decoded.size >= 36) {
            val storedChecksum = decoded.copyOfRange(decoded.size - 2, decoded.size)
            val expectedChecksum = java.security.MessageDigest.getInstance("SHA256")
                .digest(publicKeyBytes)
                .copyOfRange(0, 2)
            if (!storedChecksum.contentEquals(expectedChecksum)) {
                Timber.w("Checksum verification failed")
                return null
            }
        }

        publicKeyBytes.joinToString("") { String.format("%02x", it) }
    } catch (e: Exception) {
        Timber.e("Failed to extract public key from peer ID $peerId: ${e.message}")
        null
    }
}

fun generateLibp2pPeerIdFromPublicKey(publicKey: String): String {
    return try {
        if (!isValidPublicKey(publicKey)) {
            Timber.w("Invalid public key format for peer ID generation: ${publicKey.take(8)}...")
            return generateFallbackPeerId(publicKey)
        }

        // Decode hex public key to bytes
        val publicKeyBytes = publicKey.hexToBytes()
        if (publicKeyBytes.size != 32) {
            Timber.w("Public key must be 32 bytes for Ed25519")
            return generateFallbackPeerId(publicKey)
        }

        // Create multihash: 0x12 (Ed25519) + 32-byte key
        val multihash = ByteBuffer.allocate(34)
            .put(0x12.toByte())
            .put(publicKeyBytes)
            .array()

        // Add SHA256 checksum (first 2 bytes)
        val sha256 = java.security.MessageDigest.getInstance("SHA256")
        val checksum = sha256.digest(multihash).copyOfRange(0, 2)

        val fullData = ByteBuffer.allocate(36)
            .put(multihash)
            .put(checksum)
            .array()

        // Encode to base58
        val base58Encoded = base58Encode(fullData)
        if (base58Encoded == null) {
            Timber.w("Base58 encoding failed")
            return generateFallbackPeerId(publicKey)
        }

        base58Encoded
    } catch (e: Exception) {
        Timber.e("Failed to generate peer ID from public key: ${e.message}")
        generateFallbackPeerId(publicKey)
    }
}

private fun generateFallbackPeerId(publicKey: String): String {
    // Create a deterministic but non-standard peer ID
    // Format: peer_<first_8_chars_of_key>
    val keyPrefix = publicKey.take(8)
    return "peer_${keyPrefix.lowercase()}"
}

fun isValidPublicKey(key: String): Boolean {
    return key.length == 64 && key.matches(Regex("[0-9a-fA-F]+"))
}

fun isValidPeerId(peerId: String): Boolean {
    return isLibp2pPeerId(peerId)
}

private fun isLibp2pPeerId(peerId: String): Boolean {
    // Base58-encoded libp2p peer IDs: 12D3KooW... (~52 chars) or Qm... (~46 chars)
    val base58Chars = peerId.all { c -> c.isLetterOrDigit() && c !in "0OIl" }
    return base58Chars && (
        (peerId.startsWith("12D3Koo") && peerId.length in 46..56) ||
        (peerId.startsWith("Qm") && peerId.length in 44..50)
    )
}

fun extractPeerIdFromPublicKey(publicKey: String): String {
    return generateLibp2pPeerIdFromPublicKey(publicKey)
}

private fun String.hexToBytes(): ByteArray {
    check(length % 2 == 0) { "Hex string must have even length" }
    return chunked(2).map { it.toInt(16).toByte() }.toByteArray()
}

private fun Int.toHex(): String = String.format("%02x", this)

// --- Base58 encoding/decoding implementation ---
// Using a simple implementation without external dependencies

private val BASE58_ALPHABET = "123456789ABCDEFGHJKLMNPQRSTUVWXYZabcdefghijkmnopqrstuvwxyz"
private val BASE58_CHARSET = BASE58_ALPHABET.toCharArray()
private val BASE58_MAP = IntArray(128) { -1 }

private fun base58Encode(data: ByteArray): String? {
    if (data.isEmpty()) return "1"

    // Count leading zeros
    var zeroCount = 0
    while (zeroCount < data.size && data[zeroCount] == 0.toByte()) {
        zeroCount++
    }

    // Convert to base58
    val encoded = StringBuilder()
    var carry = data.clone()

    // Big integer division by 58
    var leadingZero = true
    while (true) {
        var carryValue = 0
        var j = 0
        while (j < carry.size) {
            carryValue = (carryValue shl 8) + (carry[j].toInt() and 0xFF)
            carry[j] = (carryValue / 58).toByte()
            carryValue %= 58
            j++
        }

        if (carryValue > 0) {
            val charIndex = carryValue
            if (leadingZero && charIndex == 0) {
                encoded.append('1')
            } else {
                encoded.append(BASE58_ALPHABET[charIndex])
                leadingZero = false
            }
        } else if (!leadingZero) {
            break
        }

        // Remove processed bytes
        val newCarry = ByteArray(carry.size - j)
        System.arraycopy(carry, j, newCarry, 0, newCarry.size)
        carry = newCarry
    }

    // Add leading '1's for leading zeros
    for (i in 0 until zeroCount) {
        encoded.insert(0, '1')
    }

    return encoded.toString().ifEmpty { null }
}

private fun base58Decode(str: String): ByteArray? {
    if (str.isEmpty()) return null

    // Count leading '1's (leading zeros)
    var zeroCount = 0
    for (c in str) {
        if (c == '1') zeroCount++
        else break
    }

    // Decode each character
    val bytes = ByteArray(str.length)
    var position = 0

    for (c in str) {
        val digit = if (c.code < BASE58_MAP.size) BASE58_MAP[c.code] else -1
        if (digit == -1) {
            Timber.w("Invalid base58 character: $c")
            return null
        }

        // Multiply by 58 and add digit
        var carry = digit
        for (i in position downTo 0) {
            carry += bytes[i].toInt() * 58
            bytes[i] = (carry and 0xFF).toByte()
            carry = carry ushr 8
        }

        while (carry > 0) {
            bytes[position] = (carry and 0xFF).toByte()
            position++
            carry = carry ushr 8
        }
    }

    // Remove leading zeros
    val result = ByteArray(bytes.size - zeroCount)
    System.arraycopy(bytes, zeroCount, result, 0, result.size)

    return result
}

private fun handleSingleShare(context: Context, intent: Intent) {
    val type = intent.type
    if (type == null) {
        Timber.w("Share intent has no type")
        return
    }

    when {
        type == "text/plain" -> {
            val sharedText = intent.getStringExtra(Intent.EXTRA_TEXT)
            if (sharedText != null) {
                showContactPicker(context, sharedText)
            } else {
                Timber.w("Shared text is null")
            }
        }
        else -> {
            Toast.makeText(context, "Unsupported share type: $type", Toast.LENGTH_SHORT).show()
            Timber.w("Unsupported share type: $type")
        }
    }
}

private fun handleMultipleShare(context: Context, intent: Intent) {
    val textItems = intent.getCharSequenceArrayListExtra(Intent.EXTRA_TEXT)
        ?.map { it.toString().trim() }
        ?.filter { it.isNotEmpty() }
        .orEmpty()

    val streamItems = IntentCompat.getParcelableArrayListExtra(intent, Intent.EXTRA_STREAM, Uri::class.java)
        ?.map { it.toString() }
        ?.filter { it.isNotBlank() }
        .orEmpty()

    if (textItems.isEmpty() && streamItems.isEmpty()) {
        Toast.makeText(context, "No shareable items found", Toast.LENGTH_SHORT).show()
        Timber.w("ACTION_SEND_MULTIPLE had no supported payloads")
        return
    }

    val content = buildString {
        if (textItems.isNotEmpty()) {
            append("Shared text items:")
            textItems.forEachIndexed { index, item ->
                append("\n${index + 1}. $item")
            }
        }
        if (streamItems.isNotEmpty()) {
            if (isNotEmpty()) append("\n\n")
            append("Shared attachments (URI references):")
            streamItems.forEachIndexed { index, uri ->
                append("\n${index + 1}. $uri")
            }
        }
    }

    showContactPicker(context, content)
}

private fun showContactPicker(context: Context, content: String) {
    try {
        val repository = MeshRepository(context.applicationContext)
        val contacts = repository.listContacts()

        if (contacts.isEmpty()) {
            Toast.makeText(context, "No contacts available", Toast.LENGTH_SHORT).show()
            Timber.w("No contacts to share with")
            return
        }

        val contactNames = contacts.map { contact ->
            contact.nickname ?: contact.peerId.take(8)
        }.toTypedArray()

        // NOTE: Showing AlertDialog from BroadcastReceiver context can fail on newer
        // Android versions due to background UI restrictions. For production, this should
        // launch a transparent Activity to handle the share flow.
        // For now, attempt dialog but catch WindowManager.BadTokenException
        try {
            AlertDialog.Builder(context)
                .setTitle("Share to Contact")
                .setItems(contactNames) { dialog, which ->
                    val selectedContact = contacts[which]
                    sendMessageToContact(context, repository, selectedContact.peerId, content)
                    dialog.dismiss()
                }
                .setNegativeButton(R.string.cancel) { dialog, _ ->
                    dialog.dismiss()
                }
                .show()
        } catch (e: android.view.WindowManager.BadTokenException) {
            Timber.w("Cannot show dialog from BroadcastReceiver context, using toast fallback")
            Toast.makeText(
                context,
                "Open SCMessenger to share content with contacts",
                Toast.LENGTH_LONG
            ).show()
        }
    } catch (e: Exception) {
        Timber.e(e, "Failed to show contact picker")
        Toast.makeText(context, "Failed to load contacts", Toast.LENGTH_SHORT).show()
    }
}

fun performStartupMaintenance(context: Context) {
    Timber.d("Performing startup storage maintenance...")

    // 1. Consolidate and rotate logs
    rotateLogsOnStartup(context)

    // 2. Clear application cache (noisy/temporary)
    clearCache(context)

    // 3. Prune oversized non-critical storage
    pruneNoisyStorage(context)

    // 4. Prune files older than 30 days (but protect critical files)
    pruneOldFiles(context)

    Timber.d("Startup maintenance complete. Available storage: ${getAvailableStorageMB(context)} MB")
}

private fun rotateLogsOnStartup(context: Context) {
    val logFile = File(context.filesDir, "mesh_diagnostics.log")
    if (!logFile.exists() || logFile.length() == 0L) return

    try {
        // Shift existing historical logs: .4 -> .5, .3 -> .4, etc.
        for (i in LOG_MAX_HISTORY - 1 downTo 1) {
            val current = File(context.filesDir, "mesh_diagnostics.log.$i")
            val next = File(context.filesDir, "mesh_diagnostics.log.${i + 1}")
            if (current.exists()) {
                if (next.exists()) next.delete()
                current.renameTo(next)
            }
        }

        // Move current log to .1
        val firstHistory = File(context.filesDir, "mesh_diagnostics.log.1")
        if (firstHistory.exists()) firstHistory.delete()
        logFile.renameTo(firstHistory)

        // Cleanup legacy .old files from previous versions
        File(context.filesDir, "mesh_diagnostics.log.old").delete()

        Timber.d("Logs rotated successfully.")
    } catch (e: Exception) {
        Timber.e(e, "Failed to rotate logs")
    }
}

private fun clearCache(context: Context) {
    try {
        val cacheSize = getDirSize(context.cacheDir)
        if (cacheSize > 0) {
            Timber.d("Clearing cache (${cacheSize / 1024} KB)...")
            context.cacheDir.deleteRecursively()
            context.cacheDir.mkdirs()
        }
    } catch (e: Exception) {
        Timber.e(e, "Failed to clear cache")
    }
}

private fun pruneNoisyStorage(context: Context) {
    // 'inbox' and 'outbox' can grow significantly if relaying traffic.
    // We prune the 'blobs' subdirectories if they exceed a noise threshold.
    val nonCriticalDirs = listOf("inbox/blobs", "outbox/blobs")

    nonCriticalDirs.forEach { path ->
        val dir = File(context.filesDir, path)
        if (dir.exists() && dir.isDirectory) {
            val size = getDirSize(dir)
            if (size > NOISY_STORAGE_THRESHOLD_BYTES) {
                Timber.w("Pruning noisy non-critical storage at '$path' (${size / 1024 / 1024} MB)")
                dir.listFiles()?.forEach { it.delete() }
            }
        }
    }
}

private fun pruneOldFiles(context: Context) {
    val filesDir = context.filesDir
    val cutoffTime = System.currentTimeMillis() - (30L * 24 * 60 * 60 * 1000) // 30 days ago

    // List of protected critical files
    val protectedFiles = setOf(IDENTITY_DB, IDENTITY_BACKUP_PREFS)

    filesDir.listFiles()?.forEach { file ->
        // Skip directories - we only prune files
        if (file.isDirectory) return@forEach

        // Skip protected files
        if (protectedFiles.contains(file.name)) {
            Timber.d("Skipping protected file: ${file.name}")
            return@forEach
        }

        // Prune files older than 30 days
        if (file.lastModified() < cutoffTime) {
            try {
                Timber.d("Pruning old file: ${file.name} (modified: ${file.lastModified()})")
                file.delete()
            } catch (e: Exception) {
                Timber.w(e, "Failed to prune old file: ${file.name}")
            }
        }
    }
}

fun getAvailableStorageMB(context: Context): Long {
    return try {
        val stat = StatFs(context.filesDir.path)
        (stat.availableBlocksLong * stat.blockSizeLong) / (1024 * 1024)
    } catch (e: Exception) {
        Timber.e(e, "Failed to calculate available storage")
        Long.MAX_VALUE // Assume plenty if we can't tell, to avoid false alarms
    }
}

fun isStorageStateCritical(context: Context): Boolean {
    return getAvailableStorageMB(context) < CRITICAL_STORAGE_THRESHOLD_MB
}

private fun getDirSize(dir: File): Long {
    var size: Long = 0
    dir.listFiles()?.forEach { file ->
        size += if (file.isDirectory) getDirSize(file) else file.length()
    }
    return size
}

fun ULong.toEpochMillis(): Long {
    val raw = toLong()
    return if (raw >= EPOCH_MILLIS_THRESHOLD) raw else raw * 1000L
}

fun ULong.toEpochSeconds(): Long {
    val raw = toLong()
    return if (raw >= EPOCH_MILLIS_THRESHOLD) raw / 1000L else raw
}

fun ULong.formatAsDateTime(): String {
    val sdf = SimpleDateFormat("MMM d, yyyy HH:mm", Locale.getDefault())
    return sdf.format(Date(toEpochMillis()))
}

