private func appendToFile(_ content: String) {
    if !FileManager.default.fileExists(atPath: logFileURL.path) {
        // Create file if it doesn't exist
        FileManager.default.createFile(atPath: logFileURL.path, contents: nil, attributes: nil)
    }

    guard let handle = FileHandle(forWritingAtPath: logFileURL.path) else {
        print("Failed to open log file for writing")
        return
    }

    defer {
        handle.closeFile()
    }

    handle.seekToEndOfFile()
    handle.write(content.data(using: .utf8) ?? Data())
}

static func image(from string: String) -> UIImage? {
    let filter: CIFilter = CIFilter.qrCodeGenerator()
    let data: Data = Data(string.utf8)
    filter.setValue(data, forKey: "inputMessage")
    filter.setValue("Q", forKey: "inputCorrectionLevel")

    guard let outputImage = filter.outputImage else { return nil }
    let scaled: CIImage = outputImage.transformed(by: CGAffineTransform(scaleX: 12, y: 12))
    guard let cgImage = context.createCGImage(scaled, from: scaled.extent) else { return nil }
    return UIImage(cgImage: cgImage)
}

