fn test_set_idle_inhibited() {
    let mut state = detect_power_state();
    set_idle_inhibited(&mut state, true);
    assert!(state.idle_inhibited);
    set_idle_inhibited(&mut state, false);
    assert!(!state.idle_inhibited);
}

pub fn check_socket_activation() -> SocketActivationStatus {
    let listen_fds: u32 = std::env::var("LISTEN_FDS")
        .ok()
        .and_then(|v| v.parse().ok())
        .unwrap_or(0);

    let listen_pid: Option<u32> = std::env::var("LISTEN_PID")
        .ok()
        .and_then(|v| v.parse().ok());

    let our_pid = std::process::id();

    if listen_fds > 0 && listen_pid == Some(our_pid) {
        SocketActivationStatus {
            state: crate::SocketActivationState::Listening,
            activated_socket_count: listen_fds,
            listen_address: std::env::var("LISTEN_NAMES").ok(),
        }
    } else {
        SocketActivationStatus {
            state: crate::SocketActivationState::None,
            activated_socket_count: 0,
            listen_address: None,
        }
    }
}

pub fn handoff_complete(status: &SocketActivationStatus) -> SocketActivationStatus {
    SocketActivationStatus {
        state: crate::SocketActivationState::HandoffComplete,
        activated_socket_count: status.activated_socket_count,
        listen_address: status.listen_address.clone(),
    }
}

fn test_no_activation_by_default() {
    // Unset the env vars (they shouldn't be set in test environment)
    std::env::remove_var("LISTEN_FDS");
    std::env::remove_var("LISTEN_PID");

    let status = check_socket_activation();
    assert!(matches!(status.state, crate::SocketActivationState::None));
    assert_eq!(status.activated_socket_count, 0);
}

fn test_activation_detected() {
    std::env::set_var("LISTEN_FDS", "2");
    std::env::set_var("LISTEN_PID", &std::process::id().to_string());

    let status = check_socket_activation();
    assert!(matches!(
        status.state,
        crate::SocketActivationState::Listening
    ));
    assert_eq!(status.activated_socket_count, 2);

    // Cleanup
    std::env::remove_var("LISTEN_FDS");
    std::env::remove_var("LISTEN_PID");
}

fn test_handoff_complete() {
    let status = SocketActivationStatus {
        state: crate::SocketActivationState::Listening,
        activated_socket_count: 1,
        listen_address: Some("scmessenger.socket".to_string()),
    };
    let completed = handoff_complete(&status);
    assert!(matches!(
        completed.state,
        crate::SocketActivationState::HandoffComplete
    ));
    assert_eq!(completed.activated_socket_count, 1);
}

pub fn tray_status_for_state(state: crate::TrayIconState, unread: u32, peers: u32) -> TrayStatus {
    let text = match state {
        crate::TrayIconState::Disconnected => "SCMessenger — Disconnected".to_string(),
        crate::TrayIconState::Connected => {
            if peers > 0 {
                format!(
                    "SCMessenger — {peers} peer{} connected",
                    if peers == 1 { "" } else { "s" }
                )
            } else {
                "SCMessenger — Connected (no peers)".to_string()
            }
        }
        crate::TrayIconState::UnreadMessages => {
            format!(
                "SCMessenger — {unread} unread message{}",
                if unread == 1 { "" } else { "s" }
            )
        }
        crate::TrayIconState::Error => "SCMessenger — Connection error".to_string(),
    };

    build_tray_status(state, unread, peers, text)
}

fn test_tray_disconnected() {
    let status = tray_status_for_state(crate::TrayIconState::Disconnected, 0, 0);
    assert_eq!(status.connected_peers, 0);
    assert!(status.status_text.contains("Disconnected"));
}

fn test_tray_connected_with_peers() {
    let status = tray_status_for_state(crate::TrayIconState::Connected, 0, 3);
    assert_eq!(status.connected_peers, 3);
    assert!(status.status_text.contains("3"));
}

fn test_tray_unread() {
    let status = tray_status_for_state(crate::TrayIconState::UnreadMessages, 5, 2);
    assert_eq!(status.unread_count, 5);
    assert!(status.status_text.contains("5"));
}

pub fn resolve_xdg_paths() -> crate::XdgPaths {
    #[cfg(target_os = "linux")]
    {
        let data_home = std::env::var("XDG_DATA_HOME")
            .map(PathBuf::from)
            .ok()
            .filter(|p| !p.as_os_str().is_empty())
            .unwrap_or_else(|| {
                dirs::home_dir()
                    .unwrap_or_else(|| PathBuf::from("."))
                    .join(".local/share")
            });

        let config_home = std::env::var("XDG_CONFIG_HOME")
            .map(PathBuf::from)
            .ok()
            .filter(|p| !p.as_os_str().is_empty())
            .unwrap_or_else(|| {
                dirs::home_dir()
                    .unwrap_or_else(|| PathBuf::from("."))
                    .join(".config")
            });

        let cache_home = std::env::var("XDG_CACHE_HOME")
            .map(PathBuf::from)
            .ok()
            .filter(|p| !p.as_os_str().is_empty())
            .unwrap_or_else(|| {
                dirs::home_dir()
                    .unwrap_or_else(|| PathBuf::from("."))
                    .join(".cache")
            });

        let data_dir = data_home.join("scmessenger");
        let config_dir = config_home.join("scmessenger");
        let cache_dir = cache_home.join("scmessenger");
        let store_path = data_dir.join("store");

        let runtime_dir = std::env::var("XDG_RUNTIME_DIR")
            .map(PathBuf::from)
            .ok()
            .filter(|p| !p.as_os_str().is_empty())
            .map(|p| p.join("scmessenger"))
            .and_then(|p| {
                if p.exists() || std::fs::create_dir_all(&p).is_ok() {
                    Some(p.to_string_lossy().to_string())
                } else {
                    None
                }
            });

        crate::XdgPaths {
            data_dir: data_dir.to_string_lossy().to_string(),
            config_dir: config_dir.to_string_lossy().to_string(),
            cache_dir: cache_dir.to_string_lossy().to_string(),
            runtime_dir,
            store_path: store_path.to_string_lossy().to_string(),
        }
    }

    #[cfg(not(target_os = "linux"))]
    {
        // Non-Linux fallback: use dirs crate defaults
        let data_dir = dirs::data_dir()
            .unwrap_or_else(|| PathBuf::from("."))
            .join("scmessenger");
        let config_dir = dirs::config_dir()
            .unwrap_or_else(|| PathBuf::from("."))
            .join("scmessenger");
        let cache_dir = dirs::cache_dir()
            .unwrap_or_else(|| PathBuf::from("."))
            .join("scmessenger");

        crate::XdgPaths {
            data_dir: data_dir.to_string_lossy().to_string(),
            config_dir: config_dir.to_string_lossy().to_string(),
            cache_dir: cache_dir.to_string_lossy().to_string(),
            runtime_dir: None,
            store_path: data_dir.join("store").to_string_lossy().to_string(),
        }
    }
}

pub fn default_store_path() -> String {
    resolve_xdg_paths().store_path
}

pub fn ensure_directories(paths: &crate::XdgPaths) -> Result<(), String> {
    for dir in [&paths.data_dir, &paths.config_dir, &paths.cache_dir] {
        std::fs::create_dir_all(dir)
            .map_err(|e| format!("Failed to create directory {dir}: {e}"))?;
    }
    Ok(())
}

fn test_xdg_paths_returns_non_empty() {
    let paths = resolve_xdg_paths();
    assert!(!paths.data_dir.is_empty());
    assert!(!paths.config_dir.is_empty());
    assert!(!paths.cache_dir.is_empty());
    assert!(!paths.store_path.is_empty());
}

